CREATE OR REPLACE FUNCTION "public"."bob_execute_read_query"("query_text" "text", "row_limit" integer DEFAULT 200, "timeout_ms" integer DEFAULT 5000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  cleaned text;
  lowered text;
  wrapped text;
  result jsonb;
begin
  cleaned := btrim(query_text);
  -- Strip a single trailing semicolon (allowed), then forbid any remaining one
  -- (blocks statement chaining / injection of a second statement).
  cleaned := regexp_replace(cleaned, ';\s*$', '');
  if position(';' in cleaned) > 0 then
    raise exception 'Only a single statement is allowed';
  end if;

  lowered := lower(cleaned);
  -- Must be a read: single SELECT or a CTE that ends in SELECT.
  if left(lowered, 6) <> 'select' and left(lowered, 4) <> 'with' then
    raise exception 'Only SELECT / WITH...SELECT queries are allowed';
  end if;
  -- Belt-and-braces keyword denylist (the READ ONLY tx is the real guard).
  if lowered ~ '\y(insert|update|delete|drop|alter|create|truncate|grant|revoke|comment|copy|merge|call|do|vacuum|analyze|reindex|refresh|set|reset)\y' then
    raise exception 'Write / DDL / session keywords are not permitted';
  end if;

  row_limit := greatest(1, least(coalesce(row_limit, 200), 2000));
  perform set_config('statement_timeout', greatest(1000, least(coalesce(timeout_ms, 5000), 20000))::text, true);

  -- Wrap in a read-only subquery with a hard row cap; aggregate queries just
  -- return their single row.
  wrapped := format('select coalesce(jsonb_agg(t), ''[]''::jsonb) from (select * from (%s) q limit %s) t', cleaned, row_limit);

  -- READ ONLY transaction block: any attempted write raises 25006.
  begin
    set transaction read only;
  exception when others then
    -- already in a read-only-capable context; ignore
    null;
  end;

  execute wrapped into result;
  return jsonb_build_object('ok', true, 'rows', coalesce(result, '[]'::jsonb), 'row_limit', row_limit);
exception when others then
  return jsonb_build_object('ok', false, 'error', sqlerrm);
end;
$_$;


ALTER FUNCTION "public"."bob_execute_read_query"("query_text" "text", "row_limit" integer, "timeout_ms" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bob_execute_read_query"("query_text" "text", "row_limit" integer, "timeout_ms" integer) IS 'Admiral-only read-only SQL for Bob. SELECT/WITH-SELECT only, single statement, row-capped, statement-timeout, executed read-only. Called by the bob-sql-read edge function AFTER it verifies the caller is grand_master. service_role execute only.';



CREATE OR REPLACE FUNCTION "public"."bob_execute_read_query_scoped"("query_text" "text", "row_limit" integer DEFAULT 50, "timeout_ms" integer DEFAULT 5000) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
declare
  cleaned text;
  lowered text;
  wrapped text;
  result jsonb;
begin
  -- Apply per-call statement timeout (local to this transaction).
  perform set_config(
    'statement_timeout',
    greatest(1000, least(coalesce(timeout_ms, 5000), 20000))::text,
    true
  );

  -- Force read-only transaction so writes are physically impossible.
  set local transaction read only;

  cleaned := btrim(query_text);
  -- Strip a single trailing semicolon, then forbid any remaining one
  -- (blocks statement chaining / injection of a second statement).
  cleaned := regexp_replace(cleaned, ';\s*$', '');
  if position(';' in cleaned) > 0 then
    raise exception 'Only a single statement is allowed';
  end if;

  lowered := lower(cleaned);
  -- Must be a read: single SELECT or a CTE that ends in SELECT.
  if left(lowered, 6) <> 'select' and left(lowered, 4) <> 'with' then
    raise exception 'Only SELECT / WITH...SELECT queries are allowed';
  end if;

  -- Belt-and-braces keyword denylist (the READ ONLY tx is the real guard).
  if lowered ~ '\y(insert|update|delete|drop|alter|create|truncate|grant|revoke|copy|vacuum|analyze|reindex|refresh)\y' then
    raise exception 'Write / DDL / session keywords are not permitted';
  end if;

  row_limit := greatest(1, least(coalesce(row_limit, 50), 2000));

  -- Wrap in a subquery with a hard row cap; aggregate queries just
  -- return their single row. RLS is enforced because this function
  -- is SECURITY INVOKER -- the caller''s role policies apply.
  wrapped := format(
    'select coalesce(jsonb_agg(t), ''[]''::jsonb) from (select * from (%s) q limit %s) t',
    cleaned,
    row_limit
  );

  execute wrapped into result;

  return jsonb_build_object(
    'ok', true,
    'rows', coalesce(result, '[]'::jsonb),
    'row_limit', row_limit
  );
exception when others then
  return jsonb_build_object('ok', false, 'error', sqlerrm);
end;
$_$;


ALTER FUNCTION "public"."bob_execute_read_query_scoped"("query_text" "text", "row_limit" integer, "timeout_ms" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bob_execute_read_query_scoped"("query_text" "text", "row_limit" integer, "timeout_ms" integer) IS 'Non-admiral read-only SQL for Bob (security invoker -- RLS applies). SELECT/WITH-SELECT only, single statement, row-capped, statement-timeout, executed read-only. Called by bob-sql-read edge function via callerClient (anon key + user JWT) for captain/commander tiers. Epic #185 E4 (#189).';



CREATE OR REPLACE FUNCTION "public"."bob_friction_packets_immutable_envelope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if OLD.envelope is distinct from NEW.envelope then
    raise exception 'envelope column is immutable once written'
      using errcode = 'restrict_violation';
  end if;
  return NEW;
end;
$$;


ALTER FUNCTION "public"."bob_friction_packets_immutable_envelope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bob_ingest_knowledge_card_384"("in_organization_id" "uuid", "in_category" "text", "in_key" "text", "in_title" "text", "in_content" "text", "in_embedding_384" "public"."vector", "in_tags" "text"[] DEFAULT '{}'::"text"[], "in_source" "text" DEFAULT NULL::"text", "in_is_active" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.bob_knowledge_cards (
    organization_id,
    category,
    key,
    title,
    content,
    tags,
    source,
    is_active,
    embedding_384,
    embedding_model,
    embedded_at
  )
  VALUES (
    in_organization_id,
    in_category,
    in_key,
    in_title,
    in_content,
    COALESCE(in_tags, '{}'),
    in_source,
    COALESCE(in_is_active, true),
    in_embedding_384,
    'gte-small',
    now()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."bob_ingest_knowledge_card_384"("in_organization_id" "uuid", "in_category" "text", "in_key" "text", "in_title" "text", "in_content" "text", "in_embedding_384" "public"."vector", "in_tags" "text"[], "in_source" "text", "in_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bob_inspect_schema"("table_names" "text"[] DEFAULT NULL::"text"[], "include_fks" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'information_schema'
    AS $$
  with cols as (
    select
      c.table_name,
      jsonb_agg(
        jsonb_build_object(
          'name', c.column_name,
          'data_type', c.data_type,
          'udt_name', c.udt_name,
          'nullable', (c.is_nullable = 'YES'),
          'default', c.column_default,
          'ordinal', c.ordinal_position
        )
        order by c.ordinal_position
      ) as columns
    from information_schema.columns c
    where c.table_schema = 'public'
      and (table_names is null or c.table_name = any(table_names))
    group by c.table_name
  ),
  cons as (
    select
      tc.table_name,
      jsonb_agg(
        jsonb_build_object(
          'constraint_name', tc.constraint_name,
          'constraint_type', tc.constraint_type
        )
      ) as constraints
    from information_schema.table_constraints tc
    where include_fks
      and tc.table_schema = 'public'
      and (table_names is null or tc.table_name = any(table_names))
    group by tc.table_name
  ),
  fks as (
    select
      tc.table_name,
      jsonb_agg(
        jsonb_build_object(
          'constraint_name', tc.constraint_name,
          'column', kcu.column_name,
          'references_table', ccu.table_name,
          'references_column', ccu.column_name
        )
        order by kcu.column_name
      ) as foreign_keys
    from information_schema.table_constraints tc
    join information_schema.key_column_usage kcu
      on kcu.constraint_name = tc.constraint_name
     and kcu.constraint_schema = tc.constraint_schema
    join information_schema.constraint_column_usage ccu
      on ccu.constraint_name = tc.constraint_name
     and ccu.constraint_schema = tc.constraint_schema
    where include_fks
      and tc.table_schema = 'public'
      and tc.constraint_type = 'FOREIGN KEY'
      and (table_names is null or tc.table_name = any(table_names))
    group by tc.table_name
  ),
  referenced_by as (
    select
      ccu.table_name,
      jsonb_agg(
        distinct jsonb_build_object(
          'from_table', tc.table_name,
          'from_column', kcu.column_name,
          'references_column', ccu.column_name
        )
      ) as referenced_by
    from information_schema.table_constraints tc
    join information_schema.key_column_usage kcu
      on kcu.constraint_name = tc.constraint_name
     and kcu.constraint_schema = tc.constraint_schema
    join information_schema.constraint_column_usage ccu
      on ccu.constraint_name = tc.constraint_name
     and ccu.constraint_schema = tc.constraint_schema
    where include_fks
      and tc.table_schema = 'public'
      and tc.constraint_type = 'FOREIGN KEY'
      and (table_names is null or ccu.table_name = any(table_names))
    group by ccu.table_name
  )
  select coalesce(
    jsonb_build_object(
      'success', true,
      'schema', 'public',
      'include_fks', include_fks,
      'tables', jsonb_agg(
        jsonb_build_object(
          'table', cols.table_name,
          'columns', cols.columns,
          'constraints', coalesce(cons.constraints, '[]'::jsonb),
          'foreign_keys', coalesce(fks.foreign_keys, '[]'::jsonb),
          'referenced_by', coalesce(referenced_by.referenced_by, '[]'::jsonb)
        )
        order by cols.table_name
      ),
      'table_count', count(*)
    ),
    jsonb_build_object('success', true, 'schema', 'public', 'tables', '[]'::jsonb, 'table_count', 0)
  )
  from cols
  left join cons on cons.table_name = cols.table_name
  left join fks on fks.table_name = cols.table_name
  left join referenced_by on referenced_by.table_name = cols.table_name;
$$;


ALTER FUNCTION "public"."bob_inspect_schema"("table_names" "text"[], "include_fks" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bob_inspect_schema"("table_names" "text"[], "include_fks" boolean) IS 'Read-only public-schema introspection. include_fks=false skips the expensive FK/constraint joins so the ALL-tables call does not hit the edge statement timeout (used by Bob''s import planner, which needs columns only). include_fks=true (default) returns relationships for scoped table lists.';



CREATE OR REPLACE FUNCTION "public"."bob_match_knowledge"("query_embedding" "public"."vector", "match_count" integer DEFAULT 5, "scope_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "category" "text", "key" "text", "title" "text", "content" "text", "tags" "text"[], "similarity" double precision)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    c.id, c.category, c.key, c.title, c.content, c.tags,
    1 - (c.embedding <=> query_embedding) as similarity
  from public.bob_knowledge_cards c
  where c.is_active
    and c.embedding is not null
    and (c.organization_id is null or c.organization_id = scope_org_id)
  order by c.embedding <=> query_embedding
  limit greatest(1, least(match_count, 20));
$$;


ALTER FUNCTION "public"."bob_match_knowledge"("query_embedding" "public"."vector", "match_count" integer, "scope_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bob_match_knowledge"("query_embedding" "public"."vector", "match_count" integer, "scope_org_id" "uuid") IS 'Semantic knowledge retrieval for Bob RAG. Returns closest active cards by cosine similarity to the query embedding, scoped to platform-canonical + the caller''s org cards. Read-only.';



CREATE OR REPLACE FUNCTION "public"."bob_match_knowledge_for_assistant_384"("in_query_embedding" "public"."vector", "in_match_threshold" double precision DEFAULT 0.72, "in_match_count" integer DEFAULT 8, "in_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "category" "text", "key" "text", "title" "text", "content" "text", "tags" "text"[], "source" "text", "similarity" double precision)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    c.id,
    c.organization_id,
    c.category,
    c.key,
    c.title,
    c.content,
    c.tags,
    c.source,
    1 - (c.embedding_384 <=> in_query_embedding) AS similarity
  FROM public.bob_knowledge_cards c
  WHERE c.is_active = true
    AND c.embedding_384 IS NOT NULL
    AND (
      c.organization_id = in_org_id
      OR c.organization_id IS NULL
    )
    AND 1 - (c.embedding_384 <=> in_query_embedding) >= in_match_threshold
  ORDER BY c.embedding_384 <=> in_query_embedding
  LIMIT GREATEST(in_match_count, 1);
$$;


ALTER FUNCTION "public"."bob_match_knowledge_for_assistant_384"("in_query_embedding" "public"."vector", "in_match_threshold" double precision, "in_match_count" integer, "in_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bob_recall_prior_context"("search_terms" "text", "scope_org_id" "uuid" DEFAULT NULL::"uuid", "max_results" integer DEFAULT 15, "lookback_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_results jsonb := '[]'::jsonb;
  v_rulings jsonb;
  v_learnings jsonb;
  v_derived jsonb;
  v_events jsonb;
  v_jobs jsonb;
  v_cutoff timestamptz;
  v_terms text;
begin
  -- Sanitise inputs
  v_terms := lower(btrim(coalesce(search_terms, '')));
  if v_terms = '' then
    return jsonb_build_object(
      'ok', false,
      'error', 'search_terms is required'
    );
  end if;

  max_results := greatest(1, least(coalesce(max_results, 15), 50));
  lookback_days := greatest(1, least(coalesce(lookback_days, 30), 365));
  v_cutoff := now() - (lookback_days || ' days')::interval;

  -- 1. Owner rulings (highest authority, always included)
  select coalesce(jsonb_agg(r order by r.created_at desc), '[]'::jsonb)
  into v_rulings
  from (
    select
      'owner_ruling'::text as source_type,
      id,
      ruling_key as key,
      title,
      ruling_text as content,
      domain as category,
      1.0::double precision as authority,
      created_at
    from public.bob_owner_rulings
    where ruling_status = 'active'
      and (
        lower(ruling_text) like '%' || v_terms || '%'
        or lower(title) like '%' || v_terms || '%'
        or lower(ruling_key) like '%' || v_terms || '%'
        or lower(domain) like '%' || v_terms || '%'
      )
    limit least(max_results, 10)
  ) r;

  -- 2. Knowledge cards with relevant categories
  select coalesce(jsonb_agg(k order by k.created_at desc), '[]'::jsonb)
  into v_learnings
  from (
    select
      'knowledge_card'::text as source_type,
      id,
      key,
      title,
      content,
      category,
      0.8::double precision as authority,
      created_at
    from public.bob_knowledge_cards
    where is_active
      and category in ('learning', 'ruling', 'discipline', 'governance')
      and (organization_id is null or organization_id = scope_org_id)
      and (
        lower(content) like '%' || v_terms || '%'
        or lower(title) like '%' || v_terms || '%'
        or lower(key) like '%' || v_terms || '%'
      )
    limit least(max_results, 10)
  ) k;

  -- 3. Derived learnings (approved + auto_digest; proposed at lower authority)
  select coalesce(jsonb_agg(d order by d.created_at desc), '[]'::jsonb)
  into v_derived
  from (
    select
      'derived_learning'::text as source_type,
      id,
      learning_key as key,
      title,
      learning_text as content,
      learning_type as category,
      case
        when learning_status = 'approved' then 0.9::double precision
        when learning_status = 'auto_digest' then 0.3::double precision
        else 0.2::double precision  -- proposed
      end as authority,
      created_at
    from public.bob_learnings
    where learning_status in ('approved', 'auto_digest', 'proposed')
      and (
        lower(learning_text) like '%' || v_terms || '%'
        or lower(title) like '%' || v_terms || '%'
        or lower(learning_key) like '%' || v_terms || '%'
      )
    limit least(max_results, 10)
  ) d;

  -- 4. Recent event_log failures/outcomes (org-scoped)
  select coalesce(jsonb_agg(e order by e.created_at desc), '[]'::jsonb)
  into v_events
  from (
    select
      'event_log'::text as source_type,
      id,
      event_type as key,
      tool as title,
      outcome as content,
      event_type as category,
      0.5::double precision as authority,
      created_at
    from public.bob_event_log
    where created_at >= v_cutoff
      and (scope_org_id is null or organization_id = scope_org_id)
      and outcome is not null
      and (
        lower(coalesce(outcome, '')) like '%' || v_terms || '%'
        or lower(coalesce(tool, '')) like '%' || v_terms || '%'
        or lower(event_type) like '%' || v_terms || '%'
      )
    limit least(max_results, 10)
  ) e;

  -- 5. Recent job_runs outcomes (org-scoped)
  select coalesce(jsonb_agg(j order by j.created_at desc), '[]'::jsonb)
  into v_jobs
  from (
    select
      'job_run'::text as source_type,
      id,
      status as key,
      goal as title,
      stopped_reason as content,
      status as category,
      0.4::double precision as authority,
      created_at
    from public.bob_job_runs
    where created_at >= v_cutoff
      and (scope_org_id is null or organization_id = scope_org_id)
      and (
        lower(coalesce(goal, '')) like '%' || v_terms || '%'
        or lower(coalesce(stopped_reason, '')) like '%' || v_terms || '%'
        or lower(status) like '%' || v_terms || '%'
      )
    limit least(max_results, 10)
  ) j;

  -- Combine all results
  v_results := v_rulings || v_learnings || v_derived || v_events || v_jobs;

  return jsonb_build_object(
    'ok', true,
    'results', v_results,
    'counts', jsonb_build_object(
      'rulings', jsonb_array_length(v_rulings),
      'learnings', jsonb_array_length(v_learnings),
      'derived', jsonb_array_length(v_derived),
      'events', jsonb_array_length(v_events),
      'jobs', jsonb_array_length(v_jobs)
    ),
    'search_terms', search_terms,
    'lookback_days', lookback_days
  );
exception when others then
  return jsonb_build_object('ok', false, 'error', sqlerrm);
end;
$$;


ALTER FUNCTION "public"."bob_recall_prior_context"("search_terms" "text", "scope_org_id" "uuid", "max_results" integer, "lookback_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bob_recall_prior_context"("search_terms" "text", "scope_org_id" "uuid", "max_results" integer, "lookback_days" integer) IS 'Runtime retrieval for Bob: queries prior owner rulings, learnings, event-log outcomes, and job-run results matching search terms. Returns a unified result set ordered by authority (rulings > learnings > events > jobs). Bob calls this via sql_read or directly as an RPC before acting on a topic where prior context may exist. Read-only. Issue #232, epic #228.';



CREATE OR REPLACE FUNCTION "public"."bob_search_reference_documents"("p_query" "text" DEFAULT NULL::"text", "p_scope" "text" DEFAULT 'both'::"text", "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_document_type" "text" DEFAULT NULL::"text", "p_jurisdiction" "text" DEFAULT NULL::"text", "p_tags" "text"[] DEFAULT NULL::"text"[], "p_allow_restricted" boolean DEFAULT false, "p_limit" integer DEFAULT 25) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_limit int := greatest(1, least(coalesce(p_limit, 25), 100));
  v_scope text := lower(coalesce(p_scope, 'both'));
  v_q text := nullif(btrim(coalesce(p_query, '')), '');
  result jsonb;
begin
  if v_scope not in ('tenant','global','both') then
    return jsonb_build_object('ok', false, 'error', 'scope must be tenant, global or both');
  end if;

  select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb)
  into result
  from (
    select
      rce.id                as catalog_entry_id,
      rce.title,
      rce.topic,
      rce.publisher,
      rce.jurisdiction,
      rce.document_type,
      rce.trust_level,
      rce.searchable_tags,
      rce.is_global_reference,
      rce.organization_id,
      d.id                  as document_id,
      dv.id                 as document_version_id,
      dv.version_label,
      dv.effective_from,
      dv.effective_to,
      dc.privacy_class,
      dc.confidence         as classification_confidence,
      -- Approved retrieval handle only. Never a raw bucket path.
      ('docref:' || dv.id::text) as retrieval_handle
    from public.reference_catalog_entries rce
    join public.document_versions dv on dv.id = rce.document_version_id
    join public.documents d on d.id = dv.document_id
    left join lateral (
      select privacy_class, confidence
      from public.document_classifications c
      where c.document_version_id = dv.id
      order by c.created_at desc
      limit 1
    ) dc on true
    where rce.approval_status = 'approved'
      and d.current_scope <> 'quarantined'
      -- Scope filter
      and (
        (v_scope = 'global' and rce.is_global_reference)
        or (v_scope = 'tenant' and rce.organization_id is not distinct from p_organization_id and not rce.is_global_reference)
        or (v_scope = 'both' and (rce.is_global_reference
              or rce.organization_id is not distinct from p_organization_id))
      )
      -- Restricted / tenant_sensitive never surface unless explicitly authorized.
      and (
        p_allow_restricted
        or coalesce(dc.privacy_class, 'restricted') in ('public','internal_non_sensitive')
        or (rce.organization_id is not distinct from p_organization_id
            and coalesce(dc.privacy_class, 'restricted') = 'tenant_sensitive')
      )
      and (p_document_type is null or rce.document_type = p_document_type)
      and (p_jurisdiction is null or rce.jurisdiction = p_jurisdiction)
      and (p_tags is null or rce.searchable_tags && p_tags)
      and (
        v_q is null
        or rce.title ilike '%' || v_q || '%'
        or coalesce(rce.topic, '') ilike '%' || v_q || '%'
        or coalesce(dv.extracted_text, '') ilike '%' || v_q || '%'
      )
    order by rce.trust_level desc, rce.updated_at desc
    limit v_limit
  ) t;

  return jsonb_build_object('ok', true, 'results', coalesce(result, '[]'::jsonb), 'scope', v_scope, 'limit', v_limit);
exception when others then
  return jsonb_build_object('ok', false, 'error', sqlerrm);
end;
$$;


ALTER FUNCTION "public"."bob_search_reference_documents"("p_query" "text", "p_scope" "text", "p_organization_id" "uuid", "p_document_type" "text", "p_jurisdiction" "text", "p_tags" "text"[], "p_allow_restricted" boolean, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bob_search_reference_documents"("p_query" "text", "p_scope" "text", "p_organization_id" "uuid", "p_document_type" "text", "p_jurisdiction" "text", "p_tags" "text"[], "p_allow_restricted" boolean, "p_limit" integer) IS 'Mediated, policy-filtered retrieval over approved reference documents for Bob. Enforces tenant/global scope, excludes quarantined and (unless authorized) restricted/tenant_sensitive material, and returns summaries + approved retrieval handles only. service_role execute only; the edge function verifies caller scope first.';



CREATE OR REPLACE FUNCTION "public"."bob_site_risk"("p_site_id" "uuid", "p_radius_m" integer DEFAULT 500, "p_unrestricted" boolean DEFAULT false, "p_scope_org_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_site        client_sites%rowtype;
  v_point       geography;
  v_radius      integer := greatest(50, least(coalesce(p_radius_m, 500), 5000));
  v_now         timestamptz := now();
  v_signals     jsonb := '[]'::jsonb;
begin
  select * into v_site from client_sites where id = p_site_id;
  if not found then
    return jsonb_build_object('success', false, 'error', 'site_not_found');
  end if;

  if v_site.center_point is not null then
    v_point := v_site.center_point::geography;
  elsif v_site.gps_lat is not null and v_site.gps_lng is not null then
    v_point := st_setsrid(st_makepoint(v_site.gps_lng, v_site.gps_lat), 4326)::geography;
  else
    v_point := null;
  end if;

  with sources as (
    select 'observation'::text as source, 'intrinsic'::text as scope,
           o.organization_id, coalesce(nullif(o.compliance_reason,''),'observation')::text as severity_hint,
           o.observed_at as occurred_at, null::numeric as distance_m,
           o.plate_number::text as detail
    from observations o
    where o.site_id = p_site_id

    union all

    select 'observation'::text, 'proximity'::text, o.organization_id, coalesce(nullif(o.compliance_reason,''),'observation')::text,
           o.observed_at,
           round(st_distance(o.gps_point::geography, v_point)::numeric, 0),
           o.plate_number::text
    from observations o
    where v_point is not null and o.site_id is distinct from p_site_id
      and o.gps_point is not null
      and st_dwithin(o.gps_point::geography, v_point, v_radius)

    union all

    select 'incident'::text,
           case when i.client_site_id = p_site_id then 'intrinsic' else 'proximity' end::text,
           i.organization_id, i.severity::text, i.occurred_at,
           round(st_distance(
             case when ics.center_point is not null then ics.center_point::geography
                  else st_setsrid(st_makepoint(ics.gps_lng, ics.gps_lat),4326)::geography end,
             v_point)::numeric, 0) as distance_m,
           i.incident_type::text
    from incidents i
    join client_sites ics on ics.id = i.client_site_id
    where v_point is not null
      and (ics.center_point is not null
           or (ics.gps_lat is not null and ics.gps_lng is not null))
      and st_dwithin(
            case when ics.center_point is not null then ics.center_point::geography
                 else st_setsrid(st_makepoint(ics.gps_lng, ics.gps_lat),4326)::geography end,
            v_point, v_radius)

    union all

    select 'field_report'::text, case when r.site_id = p_site_id then 'intrinsic' else 'proximity' end::text,
           r.organization_id, r.severity::text, r.reported_at,
           case when r.gps_lat is null then null
                else round(st_distance(st_setsrid(st_makepoint(r.gps_lng, r.gps_lat),4326)::geography, v_point)::numeric,0) end,
           r.report_type::text
    from officer_field_reports r
    where (r.site_id = p_site_id)
       or (v_point is not null and r.gps_lat is not null
           and st_dwithin(st_setsrid(st_makepoint(r.gps_lng, r.gps_lat),4326)::geography, v_point, v_radius))

    union all

    select case ef.entity_type
             when 'place' then 'location_flag'
             when 'vehicle' then 'vehicle_flag'
             else 'entity_flag'
           end::text,
           case when ef.entity_type = 'place' and ef.entity_id = p_site_id then 'intrinsic'
                else 'proximity' end::text,
           ef.organization_id, ef.alert_level::text, ef.raised_at,
           case when ef.entity_type = 'place' then
             (select round(st_distance(
               case when efs.center_point is not null then efs.center_point::geography
                    else st_setsrid(st_makepoint(efs.gps_lng, efs.gps_lat),4326)::geography end,
               v_point)::numeric, 0)
              from client_sites efs where efs.id = ef.entity_id
                and (efs.center_point is not null or (efs.gps_lat is not null and efs.gps_lng is not null)))
           else null end,
           ef.flag_type::text
    from entity_flags ef
    where ef.active
      and ((ef.entity_type = 'place' and ef.entity_id = p_site_id)
        or (ef.entity_type = 'place' and v_point is not null
            and exists (
              select 1 from client_sites efs
              where efs.id = ef.entity_id
                and (efs.center_point is not null or (efs.gps_lat is not null and efs.gps_lng is not null))
                and st_dwithin(
                  case when efs.center_point is not null then efs.center_point::geography
                       else st_setsrid(st_makepoint(efs.gps_lng, efs.gps_lat),4326)::geography end,
                  v_point, v_radius)))
        or (ef.entity_type in ('vehicle', 'person', 'staff')))

    union all

    select 'welfare_alert'::text, 'proximity'::text, wa.organization_id, wa.alert_type::text, wa.triggered_at,
           case when wa.gps_lat is null then null
                else round(st_distance(st_setsrid(st_makepoint(wa.gps_lng, wa.gps_lat),4326)::geography, v_point)::numeric,0) end,
           wa.alert_type::text
    from welfare_alerts wa
    where v_point is not null and wa.gps_lat is not null
      and st_dwithin(st_setsrid(st_makepoint(wa.gps_lng, wa.gps_lat),4326)::geography, v_point, v_radius)

    union all
    select 'noise_assessment'::text, 'intrinsic'::text, n.organization_id,
           (case when n.hs_flag_active then 'high' else 'low' end)::text, n.assessed_at, null, n.noise_source::text
    from noise_assessments n where n.site_id = p_site_id

    union all
    select 'smoke_assessment'::text, 'intrinsic'::text, sm.organization_id, coalesce(sm.severity::text,'low')::text, sm.assessed_at, null, sm.smoke_source_type::text
    from smoke_assessments sm where sm.site_id = p_site_id

    union all
    select 'biosecurity_assessment'::text, 'intrinsic'::text, b.organization_id, 'low'::text, b.assessed_at, null, b.species_identified::text
    from biosecurity_assessments b where b.site_id = p_site_id
  ),
  banded as (
    select *,
      case when occurred_at >= v_now - interval '7 days'  then 'active'
           when occurred_at >= v_now - interval '28 days' then 'monitor'
           else 'history' end as band,
      (p_unrestricted
        or p_scope_org_ids is null
        or organization_id = any(p_scope_org_ids)) as in_scope
    from sources
    where occurred_at is not null
  )
  select jsonb_agg(
    jsonb_build_object(
      'source', source,
      'scope', scope,
      'band', band,
      'severity', severity_hint,
      'occurred_at', occurred_at,
      'distance_m', distance_m,
      'in_scope', in_scope,
      'detail', case when in_scope then detail else null end,
      'identity_withheld', (not in_scope)
    )
    order by occurred_at desc
  )
  into v_signals
  from banded;

  return jsonb_build_object(
    'success', true,
    'site_id', p_site_id,
    'site_name', v_site.name,
    'has_point', (v_point is not null),
    'radius_m', v_radius,
    'generated_at', v_now,
    'signals', coalesce(v_signals, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."bob_site_risk"("p_site_id" "uuid", "p_radius_m" integer, "p_unrestricted" boolean, "p_scope_org_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_vehicle_compliance"("p_plate" "text", "p_zone_id" "uuid", "p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
declare
  v_rules             zone_compliance_matrix%rowtype;
  v_zone              location_zones%rowtype;
  v_scv               canonical_scv%rowtype;
  v_streak            integer := 0;   -- current consecutive-night streak
  v_nights_month      integer := 0;   -- distinct verified nights this calendar month
  v_is_compliant      boolean := true;
  v_reason            text := 'compliant';
  v_month_start_date  date := date_trunc('month', current_date)::date;
  v_rule_type         text;
  v_scv_exempts       boolean := true;
begin
  -- Fetch zone rule_type + scv_exempts_restriction (0191).
  select * into v_zone from location_zones where id = p_zone_id;
  if found then
    v_rule_type   := coalesce(v_zone.rule_type, 'overnight_limited');
    v_scv_exempts := coalesce(v_zone.scv_exempts_restriction, true);
  else
    v_rule_type   := 'overnight_limited';
    v_scv_exempts := true;
  end if;

  -- ── GATE 1: prohibited / day_visit_only (unchanged from 0194) ────────────
  if v_rule_type in ('prohibited', 'day_visit_only') then
    select count(distinct overnight_date)
    into v_streak
    from vehicle_overnight_sessions
    where
      plate_number = p_plate
      and zone_id = p_zone_id
      and organization_id = p_org_id
      and verification_status = 'verified_overnight'
      and overnight_date >= v_month_start_date;

    if v_streak > 0 then
      return jsonb_build_object(
        'is_compliant',      false,
        'reason',            'no_overnight_permitted',
        'nights_this_zone',  v_streak,
        'nights_this_month', v_streak,
        'limit_consecutive', null,
        'limit_monthly',     null,
        'scv_required',      false,
        'is_scv',            false
      );
    end if;
    return jsonb_build_object(
      'is_compliant',      true,
      'reason',            'no_overnight_yet',
      'nights_this_zone',  0,
      'nights_this_month', 0,
      'limit_consecutive', null,
      'limit_monthly',     null,
      'scv_required',      false,
      'is_scv',            false
    );
  end if;

  -- ── GATE 2: restricted / SCV gate (unchanged from 0194) ──────────────────
  if v_rule_type = 'restricted' and v_scv_exempts then
    select * into v_scv
    from canonical_scv
    where
      plate_number = p_plate
      and certificate_status = 'active'
      and (expiry_date is null or expiry_date >= current_date);

    if not found then
      return jsonb_build_object(
        'is_compliant',      false,
        'reason',            'no_scv_certificate',
        'nights_this_zone',  0,
        'nights_this_month', 0,
        'limit_consecutive', null,
        'limit_monthly',     null,
        'scv_required',      true,
        'is_scv',            false
      );
    end if;
  end if;

  -- ── Night-count path (unrestricted / overnight_limited / restricted+SCV) ──

  -- Get current compliance rules.
  select * into v_rules
  from zone_compliance_matrix
  where
    zone_id = p_zone_id
    and organization_id = p_org_id
    and is_current = true
    and effective_from <= current_date
    and (effective_to is null or effective_to >= current_date)
  order by version desc
  limit 1;

  if not found then
    return jsonb_build_object(
      'is_compliant', true,
      'reason', 'no_rules_configured',
      'nights_this_zone', 0,
      'nights_this_month', 0,
      'limit_consecutive', null,
      'limit_monthly', null,
      'scv_required', false,
      'is_scv', (v_scv.id is not null)
    );
  end if;

  -- SCV gate for overnight_limited zones (unchanged from 0194).
  if v_rule_type not in ('restricted') and v_rules.scv_required then
    if v_scv.id is null then
      select * into v_scv
      from canonical_scv
      where
        plate_number = p_plate
        and certificate_status = 'active'
        and (expiry_date is null or expiry_date >= current_date);

      if not found then
        return jsonb_build_object(
          'is_compliant', false,
          'reason', 'no_scv_certificate',
          'nights_this_zone', 0,
          'nights_this_month', 0,
          'limit_consecutive', v_rules.max_consecutive_nights,
          'limit_monthly', v_rules.max_nights_per_month,
          'scv_required', true,
          'is_scv', false
        );
      end if;
    end if;
  end if;

  -- ── COUNTER 1: consecutive streak (THE FIX) ──────────────────────────────
  -- Reads from vehicle_overnight_sessions for BOTH verification modes.
  -- For two_photo_verified: sessions created by the two-photo morning scan.
  -- For single_daily_observation: sessions created by process-officer-scan
  --   using the movement-check result (stationary -> verified_overnight).
  -- For historical import (#79): sessions with evidence_strength='inferred'.
  -- All three produce verified_overnight rows; the streak algorithm is identical.
  --
  -- Algorithm: subtract ROW_NUMBER() (as an interval) from each date.
  -- Consecutive dates produce the same anchor (streak_group); a gap of >=1
  -- day produces a different anchor. Current streak = count of dates in the
  -- group containing max(overnight_date). No cursor, no loop.
  with dated as (
    select distinct overnight_date
    from vehicle_overnight_sessions
    where
      plate_number = p_plate
      and zone_id = p_zone_id
      and organization_id = p_org_id
      and verification_status = 'verified_overnight'
  ),
  grouped as (
    select
      overnight_date,
      overnight_date
        - (row_number() over (order by overnight_date))::integer * interval '1 day'
        as streak_group
    from dated
  ),
  current_group as (
    select streak_group
    from grouped
    order by overnight_date desc
    limit 1
  )
  select coalesce(count(*), 0)
  into v_streak
  from grouped
  where streak_group = (select streak_group from current_group);

  -- ── COUNTER 2: monthly total ────────────────────────────────────────────────
  -- Distinct verified overnight nights since the 1st of the calendar month,
  -- regardless of gaps or streaks. Resets on the 1st.
  select coalesce(count(distinct overnight_date), 0)
  into v_nights_month
  from vehicle_overnight_sessions
  where
    plate_number = p_plate
    and organization_id = p_org_id
    and verification_status = 'verified_overnight'
    and overnight_date >= v_month_start_date;

  -- ── Limit comparisons ────────────────────────────────────────────────────────────
  -- BREACH fires when the count EXCEEDS the limit (> not >=).
  -- Owner-confirmed: limit=3 means 3 nights are allowed; the 4th breaches.
  -- Consecutive checked first; if both trip simultaneously, consecutive wins.

  if v_rules.max_consecutive_nights is not null
    and v_streak > v_rules.max_consecutive_nights then
    v_is_compliant := false;
    v_reason := 'consecutive_night_limit_exceeded';
  end if;

  if v_is_compliant
    and v_rules.max_nights_per_month is not null
    and v_nights_month > v_rules.max_nights_per_month then
    v_is_compliant := false;
    v_reason := 'monthly_limit_exceeded';
  end if;

  -- nights_this_zone = streak (what the consecutive limit is about).
  -- nights_this_month = monthly total (what the monthly limit is about).
  -- process-officer-scan Step 8a at_risk detection reads both and fires
  -- when streak == max_consecutive_nights OR total == max_nights_per_month
  -- (AT the limit, next night would breach) -- no code change needed there.
  return jsonb_build_object(
    'is_compliant',      v_is_compliant,
    'reason',            v_reason,
    'nights_this_zone',  v_streak,
    'nights_this_month', v_nights_month,
    'limit_consecutive', v_rules.max_consecutive_nights,
    'limit_monthly',     v_rules.max_nights_per_month,
    'scv_required',      coalesce(v_rules.scv_required, false),
    'is_scv',            (v_scv.id is not null)
  );
end;
$$;


ALTER FUNCTION "public"."calculate_vehicle_compliance"("p_plate" "text", "p_zone_id" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_vehicle_compliance"("p_plate" "text", "p_zone_id" "uuid", "p_org_id" "uuid") IS 'Compliance engine. Layer 2 (0195): two independent counters. (1) Consecutive streak (nights_this_zone): length of the current unbroken run of verified_overnight sessions, using ROW_NUMBER()-subtraction streak-group algorithm -- resets to 1 after any gap. Breach fires when streak > max_consecutive_nights (the 4th night breaches when limit is 3). (2) Monthly total (nights_this_month): count(distinct overnight_date) from verified sessions since the 1st of the calendar month, regardless of gaps. Breach fires when total > max_nights_per_month. Both limits are independent; consecutive checked first. Unified source: both two_photo_verified and single_daily_observation modes read from vehicle_overnight_sessions (sessions created by process-officer-scan using movement-check for live single-daily orgs, or by historical import with evidence_strength=inferred). Layer 1 (0194) rule_type gate runs first. Layer 0 (0193) verified-session source. #74.';



CREATE OR REPLACE FUNCTION "public"."can_approve_action"("p_user_id" "uuid", "p_action_org_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
BEGIN
  SELECT up.role INTO v_role
  FROM user_profiles up
  WHERE up.id = p_user_id;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  -- grand_master can approve anything
  IF v_role = 'grand_master' THEN
    RETURN true;
  END IF;

  -- master/admin: check tree-based access
  IF v_role IN ('master', 'admin') THEN
    -- Use a direct check mirroring is_admin_for_org but parameterized by user
    RETURN EXISTS (
      SELECT 1 FROM user_profiles up
      WHERE up.id = p_user_id
        AND (
          -- master: descendant tree
          (up.role = 'master' AND (
            p_action_org_id = ANY(get_descendant_organizations(up.employer_organization_id))
            OR p_action_org_id = ANY(get_descendant_organizations(up.organization_id))
            -- Agreement-based (0271 Model A)
            OR EXISTS (
              SELECT 1 FROM service_agreements sa
              WHERE (sa.ends_on IS NULL OR sa.ends_on >= current_date)
                AND sa.client_organization_id = p_action_org_id
                AND (up.organization_id = sa.provider_organization_id
                     OR up.employer_organization_id = sa.provider_organization_id)
            )
          ))
          OR
          -- admin: direct org or descendant tree
          (up.role = 'admin' AND (
            up.organization_id = p_action_org_id
            OR p_action_org_id = ANY(get_descendant_organizations(up.organization_id))
            -- Agreement-based (0271 Model A)
            OR EXISTS (
              SELECT 1 FROM service_agreements sa
              WHERE (sa.ends_on IS NULL OR sa.ends_on >= current_date)
                AND sa.client_organization_id = p_action_org_id
                AND (up.organization_id = sa.provider_organization_id
                     OR up.employer_organization_id = sa.provider_organization_id)
            )
          ))
        )
    );
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."can_approve_action"("p_user_id" "uuid", "p_action_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_approve_action"("p_user_id" "uuid", "p_action_org_id" "uuid") IS 'Tree-based authorization check: can user p_user_id approve actions for org p_action_org_id? Mirrors is_admin_for_org logic but parameterized by user_id (not auth.uid()). Used by bob-proposal-approver edge function. #16/#18.';



CREATE OR REPLACE FUNCTION "public"."check_invite_rate_limit"("p_caller_id" "uuid", "p_target_org_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller_count integer;
  v_org_count    integer;
begin
  -- Per-caller: max 5 invites in the last 5 minutes
  select count(*) into v_caller_count
    from invite_rate_log
   where caller_id = p_caller_id
     and attempted_at > now() - interval '5 minutes';

  if v_caller_count >= 5 then
    return false;
  end if;

  -- Per-target-org: max 1 invite in the last 2 minutes
  select count(*) into v_org_count
    from invite_rate_log
   where target_org_id = p_target_org_id
     and attempted_at > now() - interval '2 minutes';

  if v_org_count >= 1 then
    return false;
  end if;

  -- Allowed — record the attempt
  insert into invite_rate_log (caller_id, target_org_id)
  values (p_caller_id, p_target_org_id);

  return true;
end;
$$;


ALTER FUNCTION "public"."check_invite_rate_limit"("p_caller_id" "uuid", "p_target_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_invite_rate_limit"("p_caller_id" "uuid", "p_target_org_id" "uuid") IS 'Rate-limit gate for invite-org (#361). Returns true if allowed, false if rate-limited. Per-caller: 5/5min. Per-target-org: 1/2min.';



CREATE OR REPLACE FUNCTION "public"."check_repeat_stay"("p_plate" "text", "p_lat" double precision, "p_lng" double precision, "p_org_id" "uuid", "p_radius_m" integer DEFAULT 500, "p_window_nights" integer DEFAULT 1, "p_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
declare
  v_nights      integer := 0;
  v_last_seen   timestamptz;
  v_point       geography;
  v_window_start timestamptz;
begin
  if p_radius_m is null or p_radius_m <= 0
     or p_window_nights is null or p_window_nights <= 0 then
    return jsonb_build_object(
      'breach', false,
      'nights_within_radius', 0,
      'radius_m', p_radius_m,
      'window_nights', p_window_nights,
      'last_seen_at', null,
      'reason', 'rule_disabled'
    );
  end if;

  v_point := st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography;
  -- Trailing window: p_window_nights calendar days back from p_at.
  v_window_start := (p_at at time zone 'Pacific/Auckland')::date
                    - (p_window_nights - 1) * interval '1 day';

  select
    count(distinct ((observed_at at time zone 'Pacific/Auckland')::date)),
    max(observed_at)
  into v_nights, v_last_seen
  from observations
  where organization_id = p_org_id
    and plate_number = p_plate
    and gps_point is not null
    and observed_at >= v_window_start
    and observed_at <= p_at
    and st_dwithin(gps_point::geography, v_point, p_radius_m);

  return jsonb_build_object(
    'breach', v_nights >= p_window_nights,
    'nights_within_radius', coalesce(v_nights, 0),
    'radius_m', p_radius_m,
    'window_nights', p_window_nights,
    'last_seen_at', v_last_seen,
    'reason', case when v_nights >= p_window_nights
                   then 'repeat_stay_within_radius' else 'within_limit' end
  );
end;
$$;


ALTER FUNCTION "public"."check_repeat_stay"("p_plate" "text", "p_lat" double precision, "p_lng" double precision, "p_org_id" "uuid", "p_radius_m" integer, "p_window_nights" integer, "p_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_repeat_stay"("p_plate" "text", "p_lat" double precision, "p_lng" double precision, "p_org_id" "uuid", "p_radius_m" integer, "p_window_nights" integer, "p_at" timestamp with time zone) IS 'Counts distinct nights a plate was observed within p_radius_m of a point over a trailing p_window_nights window. Returns JSON verdict (breach when nights >= window). Distances via ST_DWithin on geography. NCC 500m rule.';



CREATE OR REPLACE FUNCTION "public"."claim_first_org_user"("p_org_id" "uuid", "p_user_id" "uuid", "p_display_name" "text", "p_role" "text", "p_email" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_existing_count integer;
begin
  -- Acquire an advisory lock scoped to this org. hashtext returns a stable
  -- int4 hash. The lock is transaction-scoped (released on COMMIT/ROLLBACK).
  perform pg_advisory_xact_lock(hashtext(p_org_id::text));

  -- Check for existing users INSIDE the lock
  select count(*) into v_existing_count
    from user_profiles
   where organization_id = p_org_id;

  if v_existing_count > 0 then
    raise exception 'Organisation already has users — duplicate first-user prevented'
      using errcode = '23505'; -- unique_violation
  end if;

  -- Insert the first user profile
  insert into user_profiles (id, organization_id, display_name, role, email)
  values (p_user_id, p_org_id, p_display_name, p_role, p_email)
  on conflict (id) do update set
    organization_id = excluded.organization_id,
    display_name    = excluded.display_name,
    role            = excluded.role,
    email           = excluded.email;
end;
$$;


ALTER FUNCTION "public"."claim_first_org_user"("p_org_id" "uuid", "p_user_id" "uuid", "p_display_name" "text", "p_role" "text", "p_email" "text") OWNER TO "postgres";


