CREATE OR REPLACE FUNCTION "public"."evaluate_parking_compliance"("p_org_id" "uuid", "p_zone_id" "uuid", "p_plate" "text", "p_is_disabled_bay" boolean DEFAULT false, "p_sign_time_limit_minutes" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_zone_limit integer;
  v_zone_multiplier numeric;
  v_org_default integer;
  v_grace integer;
  v_effective_limit integer;
  v_chalk record;
  v_minutes_elapsed numeric;  -- C6 fix: was integer, now numeric
  v_is_overstay boolean;
  v_is_repeat boolean;
  v_repeat_count integer;
begin
  -- 1. Get zone parking rules
  select parking_time_limit_minutes, parking_disabled_multiplier
  into v_zone_limit, v_zone_multiplier
  from location_zones
  where id = p_zone_id;

  -- 2. Get org defaults
  select default_time_limit_minutes, grace_period_minutes
  into v_org_default, v_grace
  from parking_module_config
  where organization_id = p_org_id;

  v_org_default := coalesce(v_org_default, 60);
  v_grace := coalesce(v_grace, 5);
  v_zone_multiplier := coalesce(v_zone_multiplier, 1);

  -- 3. Resolve effective time limit: sign OCR > zone default > org default
  v_effective_limit := coalesce(p_sign_time_limit_minutes, v_zone_limit, v_org_default);

  -- 4. Apply disabled multiplier if disabled bay
  if p_is_disabled_bay then
    v_effective_limit := round(v_effective_limit * v_zone_multiplier);
  end if;

  -- 5. Find most recent active chalk record for this plate in this org
  -- C3 fix: when p_zone_id is specified, only match chalk records with
  -- the SAME zone_id — do NOT match null zone_id records against a
  -- specific zone query (that was a false cross-zone match bug).
  select * into v_chalk
  from parking_chalk_records
  where organization_id = p_org_id
    and plate = upper(p_plate)
    and status = 'active'
    and (
      p_zone_id is null
      or zone_id = p_zone_id
    )
  order by chalked_at desc
  limit 1;

  -- 6. Check overstay
  v_is_overstay := false;
  v_minutes_elapsed := null;
  if v_chalk.id is not null then
    v_minutes_elapsed := extract(epoch from (now() - v_chalk.chalked_at)) / 60.0;
    v_is_overstay := v_minutes_elapsed > (v_effective_limit + v_grace);
  end if;

  -- 7. Check repeat offender (other chalk records today, any status except compliant)
  -- Timezone-aware date boundary for Pacific/Auckland consistency.
  -- QA review fix: the original expression
  --   (current_timestamp at time zone 'Pacific/Auckland')::date::timestamptz
  -- was incorrect — casting a date to timestamptz re-interprets it in the
  -- SESSION timezone (UTC on Supabase), placing the boundary ~12h after
  -- true Auckland midnight. The correct idiom:
  --   date_trunc('day', current_timestamp at time zone 'Pacific/Auckland')
  --     at time zone 'Pacific/Auckland'
  -- Worked example: scan at 2026-07-15 23:55 NZST (= 11:55 UTC):
  --   current_timestamp at time zone 'Pacific/Auckland' → 2026-07-15 23:55:00
  --   date_trunc('day', ...) → 2026-07-15 00:00:00 (Auckland midnight, no tz)
  --   ... at time zone 'Pacific/Auckland' → 2026-07-14 12:00:00+00 (UTC)
  -- So chalked_at >= that value means "chalked at or after midnight NZST today". ✓
  select count(*) into v_repeat_count
  from parking_chalk_records
  where organization_id = p_org_id
    and plate = upper(p_plate)
    and chalked_at >= date_trunc('day', current_timestamp at time zone 'Pacific/Auckland') at time zone 'Pacific/Auckland'
    and status != 'compliant'
    and (v_chalk.id is null or id != v_chalk.id);

  v_is_repeat := v_repeat_count > 0;

  return jsonb_build_object(
    'verdict',                  case
                                  when v_is_overstay and v_is_repeat then 'repeat_offender'
                                  when v_is_overstay then 'overstay'
                                  when v_chalk.id is not null then 'watch'
                                  else 'clear'
                                end,
    'effective_limit_minutes',  v_effective_limit,
    'grace_period_minutes',     v_grace,
    'chalked_at',               v_chalk.chalked_at,
    'minutes_elapsed',          v_minutes_elapsed,
    'is_overstay',              v_is_overstay,
    'is_repeat',                v_is_repeat,
    'repeat_count',             v_repeat_count,
    'recommended_action',       case
                                  when v_is_overstay and v_is_repeat then 'infringement'
                                  when v_is_overstay then 'infringement'
                                  when v_chalk.id is not null then 'warning'
                                  else 'none'
                                end
  );
end;
$$;


ALTER FUNCTION "public"."evaluate_parking_compliance"("p_org_id" "uuid", "p_zone_id" "uuid", "p_plate" "text", "p_is_disabled_bay" boolean, "p_sign_time_limit_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."evaluate_parking_compliance"("p_org_id" "uuid", "p_zone_id" "uuid", "p_plate" "text", "p_is_disabled_bay" boolean, "p_sign_time_limit_minutes" integer) IS 'Evaluate parking compliance for a plate in a zone. Resolves effective time limit (sign OCR > zone default > org default), applies disabled multiplier, checks overstay and repeat offender status. Called by process-officer-scan when module_key=parking_enforcement. Issue #116. Fixed in 0233: C6 (numeric precision), C3 (zone filter tightening).';



CREATE OR REPLACE FUNCTION "public"."generate_due_report_packs"("p_period_start" "date", "p_period_end" "date") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER SET "search_path" TO 'public'
    AS $$
declare
  v_actor       uuid := auth.uid();
  v_provider    uuid;
  v_agreement   record;
  v_count       integer := 0;
  v_data        jsonb;
  v_start_ts    timestamptz := p_period_start::timestamptz;
  v_end_ts      timestamptz := (p_period_end::timestamptz + interval '1 day' - interval '1 second');
  v_sla_met     integer;
  v_sla_breached integer;
  v_sla_running integer;
  v_inc_total   integer;
  v_inc_by_sev  jsonb;
  v_checkpoints integer;
  v_breaches    integer;
  v_facilities  jsonb;
begin
  if p_period_start is null or p_period_end is null or p_period_start > p_period_end or p_period_end - p_period_start > 366 then
    raise exception 'Select a valid report period of 366 days or less';
  end if;
  select organization_id into v_provider from user_profiles where id = v_actor and deactivated_at is null;
  if v_provider is null or not is_admin_for_org(v_provider) then raise exception 'Active provider administrator required'; end if;
  for v_agreement in
    select id, organization_id, provider_organization_id, monthly_report_template_code
    from service_agreements
    where provider_organization_id = v_provider
      and monthly_report_template_code is not null
  loop
    -- SLA performance for this agreement over the period.
    select
      count(*) filter (where status = 'met'),
      count(*) filter (where status = 'breached'),
      count(*) filter (where status = 'running')
    into v_sla_met, v_sla_breached, v_sla_running
    from sla_clocks
    where service_agreement_id = v_agreement.id
      and started_at >= v_start_ts and started_at <= v_end_ts;

    -- Incidents over the period (org-wide).
    select count(*),
           coalesce(jsonb_object_agg(severity, n), '{}'::jsonb)
    into v_inc_total, v_inc_by_sev
    from (
      select severity, count(*) as n
      from incidents
      where organization_id = v_agreement.provider_organization_id
        and occurred_at >= v_start_ts and occurred_at <= v_end_ts
      group by severity
    ) s;

    select count(*) into v_checkpoints
    from patrol_checkpoint_visits
    where organization_id = v_agreement.provider_organization_id
      and visited_at >= v_start_ts and visited_at <= v_end_ts;

    select count(*) into v_breaches
    from breach_alerts
    where organization_id = v_agreement.provider_organization_id
      and created_at >= v_start_ts and created_at <= v_end_ts;

    -- Per-facility patrol completion from shift_stops.
    select coalesce(jsonb_agg(jsonb_build_object(
             'siteName', site_name,
             'expected', expected,
             'completed', completed
           ) order by site_name), '[]'::jsonb)
    into v_facilities
    from (
      select coalesce(cs.name, 'Unknown site') as site_name,
             count(*) as expected,
             count(*) filter (where ss.status = 'completed') as completed
      from shift_stops ss
      left join client_sites cs on cs.id = ss.site_id
      where ss.organization_id = v_agreement.provider_organization_id
        and ss.sla_arrive_by >= v_start_ts and ss.sla_arrive_by <= v_end_ts
      group by coalesce(cs.name, 'Unknown site')
    ) f;

    v_data := jsonb_build_object(
      'slaMet', coalesce(v_sla_met, 0),
      'slaBreached', coalesce(v_sla_breached, 0),
      'slaRunning', coalesce(v_sla_running, 0),
      'incidentsTotal', coalesce(v_inc_total, 0),
      'incidentsBySeverity', coalesce(v_inc_by_sev, '{}'::jsonb),
      'checkpointVisits', coalesce(v_checkpoints, 0),
      'breachAlerts', coalesce(v_breaches, 0),
      'facilities', coalesce(v_facilities, '[]'::jsonb)
    );

    insert into monthly_report_packs (
      organization_id, service_agreement_id, template_code,
      period_start, period_end, status, data, generated_at, generated_by, updated_at
    ) values (
      v_agreement.provider_organization_id, v_agreement.id,
      v_agreement.monthly_report_template_code,
      p_period_start, p_period_end, 'generated', v_data, now(), v_actor, now()
    )
    on conflict (service_agreement_id, template_code, period_start)
    do update set
      data = excluded.data,
      status = case when monthly_report_packs.status = 'sent' then 'sent' else 'generated' end,
      generated_at = now(),
      generated_by = v_actor,
      updated_at = now();

    v_count := v_count + 1;
  end loop;
  insert into audit_log(organization_id, actor_user_id, action, target_table, metadata)
  values(v_provider, v_actor, 'monthly_report_packs_generated', 'monthly_report_packs', jsonb_build_object('period_start', p_period_start, 'period_end', p_period_end, 'pack_count', v_count));

  return v_count;
end;
$$;


ALTER FUNCTION "public"."generate_due_report_packs"("p_period_start" "date", "p_period_end" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_due_report_packs"("p_period_start" "date", "p_period_end" "date") IS 'Assembles + upserts monthly_report_packs for every agreement with a template code over the given period. Mirrors the client-side assembler so generation can be scheduled (pg_cron). Does not re-downgrade an already-sent pack.';



