    LANGUAGE "sql"
    AS $$
  select 'NC-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('noise_job_seq')::text, 6, '0');
$$;


ALTER FUNCTION "public"."generate_noise_job_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_parking_notice_number"("p_org_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_code text;
  v_date text;
  v_seq integer;
  v_notice_number text;
begin
  select coalesce(upper(left(replace(name, ' ', ''), 4)), 'PARK')
  into v_org_code
  from organizations where id = p_org_id;

  v_date := to_char(current_date, 'YYYYMMDD');

  select coalesce(max(
    cast(right(notice_number, 4) as integer)
  ), 0) + 1
  into v_seq
  from parking_infringement_notices
  where organization_id = p_org_id
    and notice_number like 'PARK-' || v_org_code || '-' || v_date || '-%';

  v_notice_number := 'PARK-' || v_org_code || '-' || v_date || '-' || lpad(v_seq::text, 4, '0');
  return v_notice_number;
end;
$$;


ALTER FUNCTION "public"."generate_parking_notice_number"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_shift_stops"("p_shift_id" "uuid", "p_shift_date" "date") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_shift           record;
  v_config          record;
  v_stop_id         uuid;
  v_stop_count      integer := 0;
  v_visit           integer;
  v_sla_open        timestamptz;
  v_sla_arrive_by   timestamptz;
  v_sla_depart_by   timestamptz;
  v_day_of_week     integer;
  v_month           integer;
  v_module_count    integer;
BEGIN
  -- Load shift.
  SELECT * INTO v_shift FROM shifts WHERE id = p_shift_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Shift % not found', p_shift_id;
  END IF;

  v_day_of_week := extract(isodow FROM p_shift_date)::integer;
  v_month       := extract(month  FROM p_shift_date)::integer;

  -- Delete any previously generated (non-adhoc) stops for this shift.
  -- shift_stop_modules rows cascade via FK ON DELETE CASCADE (0138).
  DELETE FROM shift_stops
  WHERE shift_id = p_shift_id
    AND is_adhoc = false;

  -- Iterate over all active patrol configs for this route (site OR zone stops).
  FOR v_config IN
    SELECT cspc.*
    FROM   client_site_patrol_config cspc
    WHERE  cspc.patrol_route_id = v_shift.patrol_route_id
      AND  cspc.active = true
      AND  (array_length(cspc.active_days, 1) IS NULL
            OR v_day_of_week = ANY(cspc.active_days))
      AND  (array_length(cspc.active_months, 1) IS NULL
            OR array_length(cspc.active_months, 1) = 0
            OR v_month = ANY(cspc.active_months))
    ORDER BY cspc.preferred_stop_order, cspc.id
  LOOP
    -- Calculate SLA window from config (same rule as 0030).
    IF v_config.time_window_type = 'fixed'
       AND v_config.window_start IS NOT NULL THEN
      v_sla_open      := (p_shift_date + v_config.window_start) AT TIME ZONE 'Pacific/Auckland';
      v_sla_arrive_by := v_sla_open + (v_config.sla_arrive_within_minutes || ' minutes')::interval;
      v_sla_depart_by := v_sla_arrive_by + (v_config.sla_depart_within_minutes || ' minutes')::interval;
    ELSE
      v_sla_open      := NULL;
      v_sla_arrive_by := v_shift.scheduled_end;
      v_sla_depart_by := NULL;
    END IF;

    -- Insert one stop per required visit. PLACE XOR: set EITHER site_id OR
    -- zone_id from the config (never both) so shift_stops_place_xor holds.
    FOR v_visit IN 1..v_config.visits_per_shift LOOP
      INSERT INTO shift_stops (
        organization_id,
        shift_id,
        patrol_config_id,
        site_id,
        zone_id,
        module_key,
        stop_order,
        visit_number,
        is_adhoc,
        sla_window_open,
        sla_arrive_by,
        sla_depart_by,
        required_dwell_minutes,
        officer_instructions,
        status,
        sla_status
      ) VALUES (
        v_shift.organization_id,
        p_shift_id,
        v_config.id,
        v_config.site_id,     -- null for a zone-stop
        v_config.zone_id,     -- null for a site-stop
        v_config.module_key,  -- legacy singular (dual-write)
        (v_config.preferred_stop_order * 10) + v_visit,
        v_visit,
        false,
        v_sla_open,
        v_sla_arrive_by,
        v_sla_depart_by,
        v_config.dwell_minutes,
        v_config.officer_instructions,
        'pending',
        'on_track'
      )
      RETURNING id INTO v_stop_id;

      -- DUAL-WRITE shift_stop_modules for this stop.
      -- NOW ALSO COPIES service_agreement_module_id + service_agreement_location_id
      -- from the plan-time module rows (contract inheritance, #328).
      INSERT INTO shift_stop_modules (
        organization_id, shift_stop_id, module_key, is_required,
        service_agreement_module_id, service_agreement_location_id
      )
      SELECT
        v_shift.organization_id,
        v_stop_id,
        prsm.module_key,
        prsm.is_required,
        prsm.service_agreement_module_id,
        prsm.service_agreement_location_id
      FROM   patrol_route_stop_modules prsm
      WHERE  prsm.patrol_config_id = v_config.id
        AND  prsm.active = true
      ON CONFLICT (shift_stop_id, module_key) DO NOTHING;

      GET DIAGNOSTICS v_module_count = ROW_COUNT;
      IF v_module_count = 0 THEN
        -- No plan-time module rows: seed one from the legacy singular module_key.
        -- No contract to inherit in this fallback path (legacy config).
        INSERT INTO shift_stop_modules (
          organization_id, shift_stop_id, module_key, is_required
        )
        VALUES (v_shift.organization_id, v_stop_id, v_config.module_key, true)
        ON CONFLICT (shift_stop_id, module_key) DO NOTHING;
      END IF;

      v_stop_count := v_stop_count + 1;
    END LOOP;
  END LOOP;

  -- Update shift with stop count and generation timestamp.
  UPDATE shifts
  SET total_stops  = v_stop_count,
      generated_at = now()
  WHERE id = p_shift_id;

  RETURN v_stop_count;
END;
$$;


ALTER FUNCTION "public"."generate_shift_stops"("p_shift_id" "uuid", "p_shift_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_shift_stops"("p_shift_id" "uuid", "p_shift_date" "date") IS 'Generates shift_stops from client_site_patrol_config for a shift+date. Phase 1b (0140) + contract inheritance (0363, #328): materialises ZONE-stops, dual-writes shift_stop_modules with service_agreement_module_id + service_agreement_location_id inherited from patrol_route_stop_modules. Called by apps/api when a shift is published.';



CREATE OR REPLACE FUNCTION "public"."geometry_area_m2"("p_geojson" "jsonb") RETURNS numeric
    LANGUAGE "sql" STABLE
    AS $$
  select st_area(st_setsrid(st_geomfromgeojson(p_geojson::text), 4326)::geography)::numeric;
$$;


ALTER FUNCTION "public"."geometry_area_m2"("p_geojson" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."geometry_area_m2"("p_geojson" "jsonb") IS 'Read-only real area (square metres, geography cast for accuracy) of a supplied GeoJSON polygon. No writes, no pass/fail gate -- surfaces the actual number so a human can judge whether a shape plausibly matches the named place, since a geofence is a domain-blind boundary, not a zone_type-specific area band.';



CREATE OR REPLACE FUNCTION "public"."get_approvals_activity"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_statuses" "text"[] DEFAULT NULL::"text"[], "p_action_types" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("id" "uuid", "action_type" "text", "status" "text", "bob_reasoning" "text", "confidence_score" real, "context_table" "text", "context_summary" "text", "created_at" timestamp with time zone, "applied_at" timestamp with time zone, "approved_at" timestamp with time zone, "proposed_payload" "jsonb", "amended_payload" "jsonb", "organization_id" "uuid", "org_name" "text", "triggered_by" "uuid", "triggered_by_name" "text", "user_id" "uuid", "user_name" "text", "approved_by" "uuid", "approved_by_name" "text", "rejection_reason" "text", "error_message" "text", "result_table" "text", "result_record_id" "uuid", "assigned_approver_id" "uuid", "assigned_approver_name" "text", "can_decide" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_role    text;
  v_org_id  uuid;
begin
  if v_user_id is null then
    return;
  end if;

  select up.role, up.organization_id
  into v_role, v_org_id
  from public.user_profiles up
  where up.id = v_user_id;

  if v_role is null then
    return;
  end if;

  return query
  select
    a.id,
    a.action_type,
    a.status,
    a.bob_reasoning,
    a.confidence_score,
    a.context_table,
    a.context_summary,
    a.created_at,
    a.applied_at,
    a.approved_at,
    a.proposed_payload,
    a.amended_payload,
    a.organization_id,
    o.name as org_name,
    a.triggered_by,
    (select up1.display_name from public.user_profiles up1 where up1.id = a.triggered_by) as triggered_by_name,
    a.user_id,
    (select up2.display_name from public.user_profiles up2 where up2.id = a.user_id) as user_name,
    a.approved_by,
    (select up3.display_name from public.user_profiles up3 where up3.id = a.approved_by) as approved_by_name,
    a.rejection_reason,
    a.error_message,
    a.result_table,
    a.result_record_id,
    a.assigned_approver_id,
    (select up4.display_name from public.user_profiles up4 where up4.id = a.assigned_approver_id) as assigned_approver_name,
    case
      when a.status not in ('pending', 'pending_approval', 'proposed') then false
      when v_role = 'grand_master' then true
      when v_role in ('master', 'admin') then public.can_approve_action(v_user_id, a.organization_id)
      else false
    end as can_decide
  from public.bob_agentic_actions a
  left join public.organizations o on o.id = a.organization_id
  where (
    a.triggered_by = v_user_id
    or a.user_id = v_user_id
    or a.assigned_approver_id = v_user_id
    or (v_role = 'grand_master')
    or (v_role in ('master', 'admin') and public.is_admin_for_org(a.organization_id))
  )
  and (p_statuses is null or a.status = any(p_statuses))
  and (p_action_types is null or a.action_type = any(p_action_types))
  order by
    case when a.status in ('pending', 'proposed', 'pending_approval') then 0 else 1 end,
    a.created_at desc
  limit p_limit
  offset p_offset;
end;
$$;


ALTER FUNCTION "public"."get_approvals_activity"("p_limit" integer, "p_offset" integer, "p_statuses" "text"[], "p_action_types" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_approvals_activity"("p_limit" integer, "p_offset" integer, "p_statuses" "text"[], "p_action_types" "text"[]) IS 'Full-lifecycle approvals & activity query for the persistent page. Returns all bob_agentic_actions visible to the calling user with tree-aware org scoping, optional status/type filters, and a can_decide flag. Doorbell Slice 2, #18.';



CREATE OR REPLACE FUNCTION "public"."get_bob_active_signing_identity"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    (
      select jsonb_build_object(
        'provider', provider,
        'key_name', key_name,
        'fingerprint_sha256', fingerprint_sha256,
        'enabled', enabled
      )
      from public.bob_signing_identities
      where provider = 'gitea' and enabled = true
      order by created_at desc
      limit 1
    ),
    jsonb_build_object('provider','gitea','enabled',false)
  );
$$;


ALTER FUNCTION "public"."get_bob_active_signing_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_boundary_history"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS TABLE("id" "uuid", "entity_type" "text", "entity_id" "uuid", "boundary_source" "text", "verification_state" "text", "verified_by" "uuid", "verified_at" timestamp with time zone, "changed_by" "uuid", "changed_via" "text", "change_reason" "text", "version" integer, "created_at" timestamp with time zone, "has_boundary" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_org_id uuid;
BEGIN
  -- Org-access gate: verify the caller can access this entity's org
  IF p_entity_type = 'organization' THEN
    IF NOT org_access_allowed(p_entity_id) THEN
      RAISE EXCEPTION 'get_boundary_history: access denied for organization %', p_entity_id;
    END IF;
  ELSIF p_entity_type = 'location_zone' THEN
    SELECT z.organization_id INTO v_org_id
      FROM public.location_zones z WHERE z.id = p_entity_id;
    IF NOT FOUND OR NOT org_access_allowed(v_org_id) THEN
      RAISE EXCEPTION 'get_boundary_history: access denied for location_zone %', p_entity_id;
    END IF;
  ELSIF p_entity_type = 'client_site' THEN
    SELECT s.client_organization_id INTO v_org_id
      FROM public.client_sites s WHERE s.id = p_entity_id;
    IF NOT FOUND OR NOT org_access_allowed(v_org_id) THEN
      RAISE EXCEPTION 'get_boundary_history: access denied for client_site %', p_entity_id;
    END IF;
  ELSE
    RAISE EXCEPTION 'get_boundary_history: unknown entity_type "%"', p_entity_type;
  END IF;

  -- Return history ordered newest-first.
  -- The boundary geometry column is NOT returned directly (it can be very
  -- large). Instead, has_boundary indicates whether a geometry was recorded.
  -- A future UI can fetch the full geometry for a specific version if needed.
  RETURN QUERY
    SELECT
      h.id,
      h.entity_type,
      h.entity_id,
      h.boundary_source,
      h.verification_state,
      h.verified_by,
      h.verified_at,
      h.changed_by,
      h.changed_via,
      h.change_reason,
      h.version,
      h.created_at,
      (h.boundary IS NOT NULL) AS has_boundary
    FROM public.geofence_boundary_history h
    WHERE h.entity_type = p_entity_type
      AND h.entity_id   = p_entity_id
    ORDER BY h.created_at DESC, h.version DESC;
END;
$$;


ALTER FUNCTION "public"."get_boundary_history"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_boundary_history"("p_entity_type" "text", "p_entity_id" "uuid") IS 'Returns the ordered boundary history for a geofence-bearing entity (newest first). Org-access-gated. Does not return the full geometry blob (has_boundary flag instead). Phase 4 geofence redesign (#226). A history-viewer UI is deferred to a fast-follow.';



CREATE OR REPLACE FUNCTION "public"."get_descendant_organizations"("org_id" "uuid") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with recursive org_tree as (
    select id from public.organizations where id = org_id
    union all
    select o.id from public.organizations o
      join org_tree t on o.parent_organization_id = t.id
  )
  select coalesce(array_agg(id), array[]::uuid[]) from org_tree;
$$;


ALTER FUNCTION "public"."get_descendant_organizations"("org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_descendant_organizations"("org_id" "uuid") IS 'Inclusive descendant org id array for a root org. SECURITY DEFINER (0098) so it reads the full org tree regardless of the caller RLS - required by is_master_for_org / master_manage_orgs_insert (0093). Body unchanged from 0074.';



CREATE OR REPLACE FUNCTION "public"."get_my_pending_proposals"("p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "action_type" "text", "status" "text", "bob_reasoning" "text", "confidence_score" real, "context_table" "text", "created_at" timestamp with time zone, "proposed_payload" "jsonb", "amended_payload" "jsonb", "organization_id" "uuid", "triggered_by" "uuid", "user_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_role    text;
  v_org_id  uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  SELECT up.role, up.organization_id
  INTO v_role, v_org_id
  FROM user_profiles up
  WHERE up.id = v_user_id;

  IF v_role IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    a.id,
    a.action_type,
    a.status,
    a.bob_reasoning,
    a.confidence_score,
    a.context_table,
    a.created_at,
    a.proposed_payload,
    a.amended_payload,
    a.organization_id,
    a.triggered_by,
    a.user_id
  FROM bob_agentic_actions a
  WHERE a.status IN ('pending', 'pending_approval', 'proposed')
    AND (
      -- Actions I triggered
      a.triggered_by = v_user_id
      -- Actions attributed to me (backward compat)
      OR a.user_id = v_user_id
      -- Actions explicitly assigned to me
      OR a.assigned_approver_id = v_user_id
      -- I am an eligible approver by tree/role
      OR (v_role = 'grand_master')
      OR (v_role IN ('master', 'admin') AND is_admin_for_org(a.organization_id))
    )
  ORDER BY a.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_my_pending_proposals"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_my_pending_proposals"("p_limit" integer) IS 'Tree-aware per-user bell query for pending bob_agentic_actions. Returns proposals the calling user can see: triggered_by me, user_id me, assigned to me, or I am an eligible approver by org tree. #18/#16.';



CREATE OR REPLACE FUNCTION "public"."get_open_jobs"("p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("source" "text", "job_id" "uuid", "organization_id" "uuid", "status" "text", "priority" "text", "title" "text", "starts_at" timestamp with time zone, "created_at" timestamp with time zone, "payload" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with jobs as (
    select
      'dispatch'::text as source,
      dj.id as job_id,
      dj.organization_id,
      dj.status::text as status,
      dj.priority::text as priority,
      coalesce(dj.job_type, 'dispatch job')::text as title,
      coalesce(dj.dispatched_at, dj.created_at) as starts_at,
      dj.created_at,
      jsonb_build_object(
        'client_site_id', dj.client_site_id,
        'shift_id', dj.shift_id,
        'dispatch_resource_id', dj.dispatch_resource_id,
        'sla_respond_by', dj.sla_respond_by
      ) as payload
    from public.dispatch_jobs dj
    where dj.status in ('pending', 'dispatched', 'en_route', 'on_scene')
      and public.org_access_allowed(dj.organization_id)

    union all

    select
      'shift_coverage'::text as source,
      scr.id as job_id,
      scr.organization_id,
      scr.status::text as status,
      scr.urgency::text as priority,
      'open shift coverage'::text as title,
      (scr.shift_date::timestamp + scr.start_time) at time zone 'UTC' as starts_at,
      scr.created_at,
      jsonb_build_object(
        'site_id', scr.site_id,
        'patrol_route_id', scr.patrol_route_id,
        'required_staff_count', scr.required_staff_count,
        'required_credentials', scr.required_credentials
      ) as payload
    from public.shift_coverage_requests scr
    where scr.status = 'open'
      and public.org_access_allowed(scr.organization_id)
  )
  select
    j.source,
    j.job_id,
    j.organization_id,
    j.status,
    j.priority,
    j.title,
    j.starts_at,
    j.created_at,
    j.payload
  from jobs j
  order by j.created_at desc
  limit greatest(coalesce(p_limit, 100), 1)
  offset greatest(coalesce(p_offset, 0), 0);
$$;


ALTER FUNCTION "public"."get_open_jobs"("p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_org_geofence_config"("p_org_id" "uuid", "p_config_key" "text", "p_zone_type" "text" DEFAULT NULL::"text", "p_default" integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT COALESCE(
    -- Try zone-type-specific override first
    (SELECT config_value FROM public.org_geofence_config
     WHERE organization_id = p_org_id
       AND config_key = p_config_key
       AND zone_type = p_zone_type
     LIMIT 1),
    -- Then org-wide (zone_type IS NULL)
    (SELECT config_value FROM public.org_geofence_config
     WHERE organization_id = p_org_id
       AND config_key = p_config_key
       AND zone_type IS NULL
     LIMIT 1),
    -- Platform default
    p_default
  );
$$;


ALTER FUNCTION "public"."get_org_geofence_config"("p_org_id" "uuid", "p_config_key" "text", "p_zone_type" "text", "p_default" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_org_geofence_config"("p_org_id" "uuid", "p_config_key" "text", "p_zone_type" "text", "p_default" integer) IS 'Reads an org geofence config value with zone-type-specific override -> org-wide -> platform default fallback. Platform defaults: site_provisional_radius_m=50, zone_provisional_radius_m=100, checkpoint_radius_m=5.';



CREATE OR REPLACE FUNCTION "public"."get_orgs_by_jurisdiction_point"("p_lng" double precision, "p_lat" double precision, "p_module_key" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  WITH pt AS (
    SELECT ST_SetSRID(ST_Point(p_lng, p_lat), 4326) AS geom
  ),
  -- All orgs whose VERIFIED jurisdiction contains the point
  containing_orgs AS (
    SELECT o.id, o.name
    FROM public.organizations o, pt
    WHERE o.jurisdiction_geom IS NOT NULL
      AND o.jurisdiction_verification = 'verified'
      AND ST_Contains(o.jurisdiction_geom, pt.geom)
  ),
  -- Sites whose boundary contains the point (for ownership + agreement lookups)
  containing_sites AS (
    SELECT cs.id AS site_id, cs.client_organization_id
    FROM public.client_sites cs, pt
    WHERE cs.boundary IS NOT NULL
      AND cs.boundary_verification = 'verified'
      AND ST_IsValid(cs.boundary)
      AND NOT ST_IsEmpty(cs.boundary)
      AND ST_Contains(cs.boundary, pt.geom)
  ),
  -- Zones whose boundary contains the point (for agreement lookups)
  containing_zones AS (
    SELECT lz.id AS zone_id, lz.organization_id
    FROM public.location_zones lz, pt
    WHERE lz.boundary IS NOT NULL
      AND lz.boundary_verification = 'verified'
      AND ST_IsValid(lz.boundary)
      AND NOT ST_IsEmpty(lz.boundary)
      AND ST_Contains(lz.boundary, pt.geom)
  ),
  -- (a) Agreement-based standing: org has an active service_agreement
  --     covering the module at a site/zone containing the point.
  agreement_standing AS (
    SELECT DISTINCT sa.client_organization_id AS org_id
    FROM public.service_agreements sa
    JOIN public.service_agreement_locations sal
      ON sal.service_agreement_id = sa.id
      AND sal.status = 'active'
    LEFT JOIN public.service_agreement_modules sam
      ON sam.service_agreement_id = sa.id
      AND sam.enabled = true
    WHERE (sa.ends_on IS NULL OR sa.ends_on >= current_date)
      AND (
        -- Location match: site or zone containing the point
        (sal.site_id IS NOT NULL AND sal.site_id IN (SELECT site_id FROM containing_sites))
        OR
        (sal.zone_id IS NOT NULL AND sal.zone_id IN (SELECT zone_id FROM containing_zones))
      )
      AND (
        -- Module match: when p_module_key provided, require module enabled
        p_module_key IS NULL
        OR sam.module_key = p_module_key
      )
  ),
  -- (b) Self-request standing: org OWNS the site AND module is enabled
  --     at the site via site_services.
  ownership_standing AS (
    SELECT DISTINCT cs.client_organization_id AS org_id
    FROM containing_sites cs
    WHERE (
      p_module_key IS NULL
      OR EXISTS (
        SELECT 1 FROM public.site_services ss
        WHERE ss.site_id = cs.site_id
          AND ss.organization_id = cs.client_organization_id
          AND ss.module_key = p_module_key
          AND ss.enabled = true
      )
    )
  ),
  -- Union of all orgs with standing
  standing_orgs AS (
    SELECT org_id FROM agreement_standing
    UNION
    SELECT org_id FROM ownership_standing
  )
  SELECT co.id, co.name
  FROM containing_orgs co
  WHERE (
    -- When module_key is provided, only return orgs with standing
    p_module_key IS NULL
    OR co.id IN (SELECT org_id FROM standing_orgs)
  )
  ORDER BY
    -- Standing-bearing orgs sort first even when p_module_key is NULL
    (CASE WHEN co.id IN (SELECT org_id FROM standing_orgs) THEN 0 ELSE 1 END),
    co.name;
$$;


ALTER FUNCTION "public"."get_orgs_by_jurisdiction_point"("p_lng" double precision, "p_lat" double precision, "p_module_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_orgs_by_jurisdiction_point"("p_lng" double precision, "p_lat" double precision, "p_module_key" "text") IS 'Role-aware requester picklist (0290). Returns orgs whose verified jurisdiction contains the point. When p_module_key is provided, filters to orgs with requester standing for that module (active agreement or site ownership + site_services). When omitted, backward-compatible but standing-bearing orgs sort first. Replaces geometry-only 0286.';



CREATE OR REPLACE FUNCTION "public"."get_zone_for_gps"("p_lat" double precision, "p_lng" double precision, "p_org_id" "uuid") RETURNS TABLE("site_id" "uuid", "site_name" "text", "zone_id" "uuid", "zone_name" "text", "parent_zone_id" "uuid", "compliance_rules" "jsonb", "closure_active" boolean)
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
  v_point geometry := st_setsrid(st_point(p_lng, p_lat), 4326);
  v_site_id uuid;
  v_zone_id uuid;
begin
  select id into v_site_id
  from client_sites
  where organization_id = p_org_id
    and st_dwithin(boundary, v_point, onsite_radius_meters)
  limit 1;

  if v_site_id is null then
    return;
  end if;

  select id into v_zone_id
  from location_zones
  where organization_id = p_org_id
    and st_contains(boundary, v_point)
  order by parent_zone_id nulls last
  limit 1;

  return query
  select
    cs.id,
    cs.site_name,
    lz.id,
    lz.name,
    lz.parent_zone_id,
    jsonb_build_object(
      'repeat_stay_radius_m', lz.repeat_stay_radius_m,
      'repeat_stay_window_nights', lz.repeat_stay_window_nights,
      'scv_required', lz.scv_required,
      'nightly_limit_consecutive', lz.nightly_limit_consecutive,
      'nightly_limit_monthly', lz.nightly_limit_monthly
    ),
    case when zc.id is not null then true else false end
  from client_sites cs
  left join location_zones lz on lz.id = v_zone_id
  left join zone_closures zc on zc.zone_id = v_zone_id
    and zc.active_from <= now()
    and zc.active_to >= now()
  where cs.id = v_site_id;
end;
$$;


ALTER FUNCTION "public"."get_zone_for_gps"("p_lat" double precision, "p_lng" double precision, "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_location_access"("p_site_id" "uuid", "p_zone_id" "uuid", "p_direction" "text" DEFAULT 'provider_reads_client'::"text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    -- Grand master always has access.
    public.is_grand_master()
    -- Ownership: the calling user''s org owns the location.
    or (
      p_site_id is not null
      and exists (
        select 1 from public.client_sites cs
        where cs.id = p_site_id
          and public.org_access_allowed(cs.client_organization_id)
      )
    )
    or (
      p_zone_id is not null
      and exists (
        select 1 from public.location_zones lz
        where lz.id = p_zone_id
          and public.org_access_allowed(lz.organization_id)
      )
    )
    -- Cross-org access via an active service_agreement_locations row.
    -- Direction: provider_reads_client = provider org has the agreement.
    --            client_reads_provider = client org has the agreement
    --              (Tier 1 operational results only; finance gated separately).
    or (
      p_direction = 'provider_reads_client'
      and exists (
        select 1
        from public.service_agreement_locations sal
        join public.service_agreements sa on sa.id = sal.service_agreement_id
        where sal.status = 'active'
          and (sal.site_id = p_site_id or sal.zone_id = p_zone_id)
          and public.org_access_allowed(sa.provider_organization_id)
      )
    )
    or (
      p_direction = 'client_reads_provider'
      and exists (
        select 1
        from public.service_agreement_locations sal
        join public.service_agreements sa on sa.id = sal.service_agreement_id
        where sal.status = 'active'
          and (sal.site_id = p_site_id or sal.zone_id = p_zone_id)
          and public.org_access_allowed(sa.client_organization_id)
      )
    )
    -- NEW (0270): head-contractor reads subcontracted work at the location.
    -- Depends on 0269 adding service_agreement_locations.head_contractor_org_id.
    or exists (
      select 1 from public.service_agreement_locations sal
      where sal.status = 'active'
        and (sal.site_id = p_site_id or sal.zone_id = p_zone_id)
        and sal.head_contractor_org_id is not null
        and public.org_access_allowed(sal.head_contractor_org_id)
    );
$$;


ALTER FUNCTION "public"."has_location_access"("p_site_id" "uuid", "p_zone_id" "uuid", "p_direction" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."has_location_access"("p_site_id" "uuid", "p_zone_id" "uuid", "p_direction" "text") IS 'Returns true when the calling user''s org has access to a location (site or zone), either by ownership, via an active service_agreement_locations row, or as a head contractor with subcontracted work at the location. Direction controls cross-org read: provider_reads_client (provider reads client location data) or client_reads_provider (client reads Tier 1 operational results at their location). QA gaps G1+G2 from epic #179; head-contractor visibility from epic #203 R2 #205.';



CREATE OR REPLACE FUNCTION "public"."insert_adhoc_stop"("p_shift_id" "uuid", "p_dispatch_job_id" "uuid", "p_site_id" "uuid", "p_module_key" "text", "p_sla_respond_by" timestamp with time zone, "p_officer_gps_lat" double precision, "p_officer_gps_lng" double precision) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_shift     record;
  v_stop_id   uuid;
  v_max_order integer;
begin
  select * into v_shift from shifts where id = p_shift_id;
  if not found then
    raise exception 'Shift % not found', p_shift_id;
  end if;

  -- Place adhoc stop at end of current sequence.
  select coalesce(max(stop_order), 0) into v_max_order
  from shift_stops
  where shift_id = p_shift_id
    and status = 'pending';

  insert into shift_stops (
    organization_id,
    shift_id,
    dispatch_job_id,
    site_id,
    module_key,
    stop_order,
    visit_number,
    is_adhoc,
    sla_arrive_by,
    required_dwell_minutes,
    status,
    sla_status
  ) values (
    v_shift.organization_id,
    p_shift_id,
    p_dispatch_job_id,
    p_site_id,
    p_module_key,
    v_max_order + 10,
    1,
    true,
    p_sla_respond_by,
    15,  -- default dwell for adhoc; API can update after insertion
    'pending',
    'on_track'
  )
  returning id into v_stop_id;

  -- Mark dispatch job as inserted into shift.
  update dispatch_jobs
  set shift_id          = p_shift_id,
      shift_stop_id     = v_stop_id,
      adhoc_inserted_at = now(),
      insert_gps_lat    = p_officer_gps_lat,
      insert_gps_lng    = p_officer_gps_lng,
      status            = 'dispatched'
  where id = p_dispatch_job_id;

  -- Invalidate solve cache so API re-solves with new stop.
  update patrol_solve_cache
  set invalidated_at      = now(),
      invalidation_reason = 'adhoc_inserted'
  where shift_id = p_shift_id;

  return v_stop_id;
end;
$$;


ALTER FUNCTION "public"."insert_adhoc_stop"("p_shift_id" "uuid", "p_dispatch_job_id" "uuid", "p_site_id" "uuid", "p_module_key" "text", "p_sla_respond_by" timestamp with time zone, "p_officer_gps_lat" double precision, "p_officer_gps_lng" double precision) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."insert_adhoc_stop"("p_shift_id" "uuid", "p_dispatch_job_id" "uuid", "p_site_id" "uuid", "p_module_key" "text", "p_sla_respond_by" timestamp with time zone, "p_officer_gps_lat" double precision, "p_officer_gps_lng" double precision) IS 'Inserts an adhoc dispatch job as a shift stop and invalidates the solve cache. Called by apps/api dispatch engine.';


CREATE OR REPLACE FUNCTION "public"."claim_shift_coverage"("p_request_id" "uuid", "p_expected_status" "text" DEFAULT 'open'::"text") RETURNS "public"."shift_coverage_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER SET "search_path" TO 'public' AS $$
declare v_user_id uuid := auth.uid(); v_profile public.user_profiles%rowtype; v_request public.shift_coverage_requests%rowtype;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select * into v_profile from public.user_profiles where id = v_user_id and deactivated_at is null and role in ('officer', 'admin_officer');
  if not found then raise exception 'Active officer profile required'; end if;
  select * into v_request from public.shift_coverage_requests where id = p_request_id for update;
  if not found then raise exception 'Coverage request not found'; end if;
  if v_request.organization_id <> v_profile.organization_id then raise exception 'Coverage request is outside the officer organization'; end if;
  if v_request.status <> p_expected_status then raise exception 'Coverage request changed from expected status % to %', p_expected_status, v_request.status; end if;
  if v_request.status <> 'open' then raise exception 'Coverage request is no longer open'; end if;
  if v_request.shift_date < current_date then raise exception 'Past coverage cannot be claimed'; end if;
  update public.shift_coverage_requests set status = 'claimed', claimed_by = v_user_id, claimed_at = clock_timestamp() where id = p_request_id returning * into v_request;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_request.organization_id, v_user_id, 'shift_coverage_claimed', 'shift_coverage_requests', v_request.id, jsonb_build_object('shift_date', v_request.shift_date, 'start_time', v_request.start_time, 'site_id', v_request.site_id));
  return v_request;
end;
$$;

ALTER FUNCTION "public"."claim_shift_coverage"("p_request_id" "uuid", "p_expected_status" "text") OWNER TO "postgres";

COMMENT ON FUNCTION "public"."claim_shift_coverage"("p_request_id" "uuid", "p_expected_status" "text") IS 'Atomically claims open coverage for the authenticated active officer and records audit provenance.';


CREATE OR REPLACE FUNCTION "public"."create_roster_shift"("p_officer_user_id" "uuid", "p_service_type" "text", "p_scheduled_start" timestamp with time zone, "p_scheduled_end" timestamp with time zone, "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_zone_id" "uuid" DEFAULT NULL::"uuid", "p_patrol_route_id" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text", "p_publish" boolean DEFAULT false) RETURNS "public"."shifts"
    LANGUAGE "plpgsql" SECURITY DEFINER SET "search_path" TO 'public' AS $$
declare v_actor uuid:=auth.uid(); v_profile public.user_profiles%rowtype; v_staff public.staff_profiles%rowtype; v_shift public.shifts%rowtype;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  select * into v_profile from public.user_profiles where id=p_officer_user_id and deactivated_at is null;
  if not found or v_profile.organization_id is null then raise exception 'Active officer profile not found'; end if;
  if not public.is_admin_for_org(v_profile.organization_id) then raise exception 'Not authorised to roster this officer'; end if;
  if v_profile.role not in ('officer','admin_officer') then raise exception 'Selected user is not rosterable as an officer'; end if;
  select * into v_staff from public.staff_profiles where (id=p_officer_user_id or user_id=p_officer_user_id) and organization_id=v_profile.organization_id limit 1;
  if not found or not v_staff.work_ready then raise exception 'Officer is not work ready'; end if;
  if p_scheduled_start is null or p_scheduled_end is null or p_scheduled_start>=p_scheduled_end then raise exception 'Shift end must be after shift start'; end if;
  if p_scheduled_start<now()-interval '5 minutes' or p_scheduled_end-p_scheduled_start>interval '24 hours' then raise exception 'Shift timing is outside the accepted range'; end if;
  if nullif(trim(coalesce(p_service_type,'')),'') is null then raise exception 'Service type is required'; end if;
  if exists(select 1 from public.leave_requests l where l.staff_id=v_staff.id and l.status='approved' and daterange(l.starts_on,l.ends_on,'[]') && daterange(p_scheduled_start::date,p_scheduled_end::date,'[]')) then raise exception 'Officer has approved leave during this shift'; end if;
  if exists(select 1 from public.shifts s where s.officer_user_id=p_officer_user_id and s.status not in ('declined','cancelled') and s.scheduled_end>s.scheduled_start and s.scheduled_start<p_scheduled_end and s.scheduled_end>p_scheduled_start) then raise exception 'Officer already has an overlapping shift'; end if;
  insert into public.shifts(organization_id,officer_user_id,service_type,location_id,zone_id,patrol_route_id,scheduled_start,scheduled_end,status,notes)
  values(v_profile.organization_id,p_officer_user_id,trim(p_service_type),p_location_id,p_zone_id,p_patrol_route_id,p_scheduled_start,p_scheduled_end,case when p_publish then 'published' else 'scheduled' end,nullif(trim(coalesce(p_notes,'')),'')) returning * into v_shift;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_profile.organization_id,v_actor,'roster_shift_created','shifts',v_shift.id,jsonb_build_object('officer_user_id',p_officer_user_id,'scheduled_start',p_scheduled_start,'scheduled_end',p_scheduled_end,'status',v_shift.status));
  return v_shift;
end;$$;


ALTER FUNCTION "public"."create_roster_shift"("p_officer_user_id" "uuid", "p_service_type" "text", "p_scheduled_start" timestamp with time zone, "p_scheduled_end" timestamp with time zone, "p_location_id" "uuid", "p_zone_id" "uuid", "p_patrol_route_id" "uuid", "p_notes" "text", "p_publish" boolean) OWNER TO "postgres";

COMMENT ON FUNCTION "public"."create_roster_shift"("p_officer_user_id" "uuid", "p_service_type" "text", "p_scheduled_start" timestamp with time zone, "p_scheduled_end" timestamp with time zone, "p_location_id" "uuid", "p_zone_id" "uuid", "p_patrol_route_id" "uuid", "p_notes" "text", "p_publish" boolean) IS 'Creates an authorized roster shift after work-readiness, leave, timing, and overlap checks.';


CREATE OR REPLACE FUNCTION "public"."submit_shift_debrief"("p_shift_id" "uuid", "p_client_event_id" "uuid", "p_summary" "text", "p_safety_incident_reported" boolean DEFAULT false, "p_equipment_issue_reported" boolean DEFAULT false, "p_follow_up_required" boolean DEFAULT false, "p_follow_up_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "created" boolean, "submitted_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER SET "search_path" TO 'public' AS $$
declare v_user_id uuid := auth.uid(); v_shift public.shifts%rowtype; v_debrief public.shift_debriefs%rowtype;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  if p_client_event_id is null then raise exception 'client_event_id is required'; end if;
  if char_length(trim(coalesce(p_summary, ''))) not between 10 and 5000 then raise exception 'Debrief summary must be between 10 and 5000 characters'; end if;
  if p_follow_up_required and nullif(trim(coalesce(p_follow_up_notes, '')), '') is null then raise exception 'Follow-up notes are required'; end if;
  select s.* into v_shift from public.shifts s where s.id = p_shift_id for share;
  if not found then raise exception 'Shift not found'; end if;
  if v_shift.officer_user_id <> v_user_id then raise exception 'Shift does not belong to the authenticated officer'; end if;
  if v_shift.status not in ('accepted', 'in_progress', 'completed') then raise exception 'Shift is not eligible for debrief'; end if;
  select d.* into v_debrief from public.shift_debriefs d where d.organization_id = v_shift.organization_id and d.officer_user_id = v_user_id and d.client_event_id = p_client_event_id;
  if found then return query select v_debrief.id, false, v_debrief.submitted_at; return; end if;
  if exists (select 1 from public.shift_debriefs d where d.shift_id = p_shift_id) then raise exception 'A debrief has already been submitted for this shift'; end if;
  insert into public.shift_debriefs (organization_id, shift_id, officer_user_id, client_event_id, summary, safety_incident_reported, equipment_issue_reported, follow_up_required, follow_up_notes)
  values (v_shift.organization_id, p_shift_id, v_user_id, p_client_event_id, trim(p_summary), coalesce(p_safety_incident_reported, false), coalesce(p_equipment_issue_reported, false), coalesce(p_follow_up_required, false), nullif(trim(coalesce(p_follow_up_notes, '')), '')) returning * into v_debrief;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_shift.organization_id, v_user_id, 'shift_debrief_submitted', 'shift_debriefs', v_debrief.id, jsonb_build_object('shift_id', p_shift_id, 'safety_incident_reported', v_debrief.safety_incident_reported, 'equipment_issue_reported', v_debrief.equipment_issue_reported, 'follow_up_required', v_debrief.follow_up_required));
  return query select v_debrief.id, true, v_debrief.submitted_at;
end;
$$;

ALTER FUNCTION "public"."submit_shift_debrief"("p_shift_id" "uuid", "p_client_event_id" "uuid", "p_summary" "text", "p_safety_incident_reported" boolean, "p_equipment_issue_reported" boolean, "p_follow_up_required" boolean, "p_follow_up_notes" "text") OWNER TO "postgres";

COMMENT ON FUNCTION "public"."submit_shift_debrief"("p_shift_id" "uuid", "p_client_event_id" "uuid", "p_summary" "text", "p_safety_incident_reported" boolean, "p_equipment_issue_reported" boolean, "p_follow_up_required" boolean, "p_follow_up_notes" "text") IS 'Creates one retry-safe, self-owned, append-only handover per eligible shift and audits submission.';


CREATE OR REPLACE FUNCTION "public"."complete_officer_shift"("p_shift_id" "uuid", "p_expected_status" "text") RETURNS TABLE("shift_id" "uuid", "shift_status" "text", "completed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER SET "search_path" TO 'public' AS $$
declare v_actor uuid:=auth.uid();v_shift public.shifts%rowtype;v_completed_at timestamptz:=clock_timestamp();
begin
  if v_actor is null then raise exception 'Authentication required';end if;
  select s.* into v_shift from public.shifts s where s.id=p_shift_id for update;
  if not found then raise exception 'Shift not found';end if;
  if v_shift.officer_user_id<>v_actor then raise exception 'Shift does not belong to the authenticated officer';end if;
  if v_shift.status<>p_expected_status then raise exception 'Shift changed from expected status % to %',p_expected_status,v_shift.status;end if;
  if v_shift.status<>'in_progress' then raise exception 'Only an in-progress shift can be completed';end if;
  if not exists(select 1 from public.shift_debriefs d where d.shift_id=v_shift.id and d.officer_user_id=v_actor) then raise exception 'Submit the shift debrief before completing the shift';end if;
  if exists(select 1 from public.shift_stops st where st.shift_id=v_shift.id and st.status not in('completed','skipped','cancelled')) then raise exception 'Complete or skip every shift stop before completing the shift';end if;
  if exists(select 1 from public.shift_stop_modules sm join public.shift_stops st on st.id=sm.shift_stop_id where st.shift_id=v_shift.id and sm.is_required and sm.status not in('completed','skipped')) then raise exception 'Complete or skip every required module task before completing the shift';end if;
  if exists(select 1 from public.dispatch_jobs j where j.shift_id=v_shift.id and j.status not in('completed','cancelled')) then raise exception 'Complete or cancel every dispatch job before completing the shift';end if;
  if exists(select 1 from public.welfare_alerts w where w.shift_id=v_shift.id and w.status<>'resolved') then raise exception 'Resolve active welfare alerts before completing the shift';end if;
  update public.shifts set status='completed',actual_end=coalesce(actual_end,v_completed_at) where id=v_shift.id returning * into v_shift;
  update public.roster_slots set status='completed',updated_at=v_completed_at where linked_shift_id=v_shift.id and status in('published','accepted');
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_shift.organization_id,v_actor,'officer_shift_completed','shifts',v_shift.id,jsonb_build_object('previous_status',p_expected_status,'actual_end',v_shift.actual_end));
  return query select v_shift.id,v_shift.status,v_shift.actual_end;
end;
$$;

ALTER FUNCTION "public"."complete_officer_shift"("p_shift_id" "uuid", "p_expected_status" "text") OWNER TO "postgres";

COMMENT ON FUNCTION "public"."complete_officer_shift"("p_shift_id" "uuid", "p_expected_status" "text") IS 'Allows the owning officer to complete an in-progress shift only after debrief and all operational, module, dispatch, and welfare work is terminal.';



CREATE OR REPLACE FUNCTION "public"."create_dispatch_job"("p_organization_id" "uuid", "p_service_agreement_id" "uuid", "p_client_site_id" "uuid", "p_client_request_id" "uuid", "p_job_type" "text", "p_priority" "text", "p_sla_minutes" integer, "p_dispatch_resource_id" "uuid" DEFAULT NULL::"uuid", "p_briefing_notes" "text" DEFAULT NULL::"text", "p_shift_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "created" boolean, "status" "text", "sla_respond_by" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_existing dispatch_jobs%rowtype;
  v_created dispatch_jobs%rowtype;
  v_resource dispatch_resources%rowtype;
  v_shift shifts%rowtype;
begin
  if not public.is_admin_for_org(p_organization_id) then
    raise exception 'Not authorised to create dispatch jobs for this organisation';
  end if;

  if p_sla_minutes is null or p_sla_minutes < 1 or p_sla_minutes > 1440 then
    raise exception 'SLA minutes must be between 1 and 1440';
  end if;

  if not exists (
    select 1
    from service_agreements sa
    join service_agreement_locations sal on sal.service_agreement_id = sa.id
    join client_sites cs on cs.id = sal.site_id
    where sa.id = p_service_agreement_id
      and sa.provider_organization_id = p_organization_id
      and sal.site_id = p_client_site_id
      and sal.status = 'active'
      and cs.active = true
  ) then
    raise exception 'Site is not active under this service agreement';
  end if;

  select * into v_existing
  from dispatch_jobs
  where organization_id = p_organization_id
    and client_request_id = p_client_request_id;

  if found then
    return query select v_existing.id, false, v_existing.status, v_existing.sla_respond_by;
    return;
  end if;

  if p_dispatch_resource_id is not null then
    if p_shift_id is null then raise exception 'A shift is required when dispatching to a resource'; end if;
    select * into v_resource from dispatch_resources
    where id = p_dispatch_resource_id and organization_id = p_organization_id for update;
    if not found or v_resource.status <> 'available' or v_resource.assigned_officer_id is null then
      raise exception 'Dispatch resource is not available with an assigned officer';
    end if;
    select * into v_shift from shifts
    where id = p_shift_id and organization_id = p_organization_id and status in ('accepted', 'in_progress') for share;
    if not found or v_shift.officer_user_id <> v_resource.assigned_officer_id then
      raise exception 'Shift officer does not match the selected dispatch resource';
    end if;
  end if;

  begin
    insert into dispatch_jobs (
      organization_id, service_agreement_id, client_site_id, client_request_id,
      dispatch_resource_id, job_type, priority, status, sla_minutes, sla_respond_by,
      briefing_notes, shift_id, dispatched_at
    ) values (
      p_organization_id, p_service_agreement_id, p_client_site_id, p_client_request_id,
      p_dispatch_resource_id, p_job_type, p_priority,
      case when p_dispatch_resource_id is null then 'pending' else 'dispatched' end, p_sla_minutes,
      now() + make_interval(mins => p_sla_minutes), nullif(trim(p_briefing_notes), ''),
      p_shift_id, case when p_dispatch_resource_id is null then null else now() end
    ) returning * into v_created;
    if p_dispatch_resource_id is not null then
      update dispatch_resources set status = 'busy' where id = p_dispatch_resource_id;
    end if;
  exception when unique_violation then
    select * into v_created
    from dispatch_jobs
    where organization_id = p_organization_id
      and client_request_id = p_client_request_id;
    return query select v_created.id, false, v_created.status, v_created.sla_respond_by;
    return;
  end;

  return query select v_created.id, true, v_created.status, v_created.sla_respond_by;
end;
$$;


ALTER FUNCTION "public"."create_dispatch_job"("p_organization_id" "uuid", "p_service_agreement_id" "uuid", "p_client_site_id" "uuid", "p_client_request_id" "uuid", "p_job_type" "text", "p_priority" "text", "p_sla_minutes" integer, "p_dispatch_resource_id" "uuid", "p_briefing_notes" "text", "p_shift_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_dispatch_job"("p_organization_id" "uuid", "p_service_agreement_id" "uuid", "p_client_site_id" "uuid", "p_client_request_id" "uuid", "p_job_type" "text", "p_priority" "text", "p_sla_minutes" integer, "p_dispatch_resource_id" "uuid", "p_briefing_notes" "text", "p_shift_id" "uuid") IS 'Idempotent admin dispatch creation with optional atomic resource assignment and SLA ownership.';

CREATE OR REPLACE FUNCTION "public"."advance_dispatch_job_status"("p_job_id" "uuid", "p_expected_status" "text", "p_next_status" "text", "p_outcome_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "status" "text", "shift_id" "uuid", "completed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER SET "search_path" TO 'public'
    AS $$
declare
  v_job dispatch_jobs%rowtype;
  v_allowed boolean := false;
begin
  select * into v_job from dispatch_jobs where dispatch_jobs.id = p_job_id for update;
  if not found then raise exception 'Dispatch job not found'; end if;
  if not is_admin_for_org(v_job.organization_id) and not exists (
    select 1 from dispatch_resources dr where dr.id = v_job.dispatch_resource_id and dr.assigned_officer_id = auth.uid()
  ) then raise exception 'Not authorised to update this dispatch job'; end if;
  if v_job.status <> p_expected_status then raise exception 'Dispatch job changed from expected status'; end if;
  v_allowed := case v_job.status
    when 'pending' then p_next_status in ('dispatched', 'cancelled')
    when 'dispatched' then p_next_status in ('acknowledged', 'en_route', 'cancelled')
    when 'acknowledged' then p_next_status in ('en_route', 'cancelled')
    when 'en_route' then p_next_status in ('on_scene', 'cancelled')
    when 'on_scene' then p_next_status in ('completed', 'cancelled')
    else false end;
  if not v_allowed then raise exception 'Invalid dispatch transition'; end if;
  if p_next_status in ('completed', 'cancelled') and nullif(trim(p_outcome_notes), '') is null then
    raise exception 'Outcome notes are required for terminal dispatch transitions';
  end if;
  update dispatch_jobs set status = p_next_status,
    acknowledged_at = case when p_next_status = 'acknowledged' then now() else acknowledged_at end,
    en_route_at = case when p_next_status = 'en_route' then now() else en_route_at end,
    on_scene_at = case when p_next_status = 'on_scene' then now() else on_scene_at end,
    completed_at = case when p_next_status = 'completed' then now() else completed_at end,
    outcome_notes = case when p_next_status in ('completed', 'cancelled') then nullif(trim(p_outcome_notes), '') else outcome_notes end
  where dispatch_jobs.id = p_job_id;
  if p_next_status in ('completed', 'cancelled') and v_job.dispatch_resource_id is not null and not exists (
    select 1 from dispatch_jobs other where other.dispatch_resource_id = v_job.dispatch_resource_id
      and other.id <> p_job_id and other.status in ('dispatched', 'acknowledged', 'en_route', 'on_scene')
  ) then update dispatch_resources set status = 'available' where id = v_job.dispatch_resource_id; end if;
  return query
  select updated.id, updated.status, updated.shift_id, updated.completed_at
  from dispatch_jobs updated
  where updated.id = p_job_id;
end;
$$;

ALTER FUNCTION "public"."advance_dispatch_job_status"("p_job_id" "uuid", "p_expected_status" "text", "p_next_status" "text", "p_outcome_notes" "text") OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "public"."is_admin_for_org"("target_org_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1 from user_profiles
    where id = auth.uid()
      and role in ('grand_master', 'master', 'admin')
      and (
        -- [EXISTING] grand_master: unrestricted
        role = 'grand_master'
        -- [EXISTING] master: check descendant tree (employer or org)
        or (role = 'master' and (
          target_org_id = any (public.get_descendant_organizations(employer_organization_id))
          or target_org_id = any (public.get_descendant_organizations(organization_id))
          -- [NEW — 0271] Agreement-based: master at provider can manage client
          or exists (
            select 1 from public.service_agreements sa
            where (sa.ends_on is null or sa.ends_on >= current_date)
              and sa.client_organization_id = target_org_id
              and (organization_id = sa.provider_organization_id
                   or employer_organization_id = sa.provider_organization_id)
          )
        ))
        -- [EXISTING] admin: direct org match OR descendant tree
        or (role = 'admin' and (
          organization_id = target_org_id
          or target_org_id = any (public.get_descendant_organizations(organization_id))
          -- [NEW — 0271] Agreement-based: admin at provider can manage client
          or exists (
            select 1 from public.service_agreements sa
            where (sa.ends_on is null or sa.ends_on >= current_date)
              and sa.client_organization_id = target_org_id
              and (organization_id = sa.provider_organization_id
                   or employer_organization_id = sa.provider_organization_id)
          )
        ))
      )
  );
$$;


ALTER FUNCTION "public"."is_admin_for_org"("target_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_admin_for_org"("target_org_id" "uuid") IS 'Returns true if the current user is admin, master, or grand_master for the target org. Admin/master check the org descendant tree (via get_descendant_organizations) and agreement-based provider access (0271 Model A). Grand master has unrestricted access.';



CREATE OR REPLACE FUNCTION "public"."is_grand_master"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  select exists (
    select 1 from public.user_profiles
    where id = auth.uid() and role = 'grand_master'
  );
$$;


ALTER FUNCTION "public"."is_grand_master"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_grand_master"() IS 'Returns true if the current user has the grand_master role.';



CREATE OR REPLACE FUNCTION "public"."is_master_for_org"("p_org_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  select exists (
    select 1 from public.user_profiles up
    where up.id = auth.uid()
      and up.role = 'master'
      and (
        -- [EXISTING] Descendant tree of employer_organization_id
        p_org_id = any (public.get_descendant_organizations(up.employer_organization_id))
        -- [EXISTING] Descendant tree of organization_id
        or p_org_id = any (public.get_descendant_organizations(up.organization_id))
        -- [NEW — 0271] Agreement-based: master at the PROVIDER org
        -- can manage the CLIENT org on an active agreement.
        or exists (
          select 1 from public.service_agreements sa
          where (sa.ends_on is null or sa.ends_on >= current_date)
            and sa.client_organization_id = p_org_id
            and (up.organization_id = sa.provider_organization_id
                 or up.employer_organization_id = sa.provider_organization_id)
        )
      )
  );
$$;


ALTER FUNCTION "public"."is_master_for_org"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_master_for_org"("p_org_id" "uuid") IS 'True when the current user is a master and p_org_id is within their authorised org tree (employer_organization_id or organization_id descendants) OR the user is a master at the provider org on an active service_agreement with p_org_id as client (0271 Model A). Scopes master self-management; never grants delete.';



CREATE OR REPLACE FUNCTION "public"."is_master_or_above"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1 from public.user_profiles
    where id = auth.uid() and role in ('grand_master', 'master')
  );
$$;


ALTER FUNCTION "public"."is_master_or_above"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_master_or_above"() IS 'True if the current user is master or grand_master. Gate for runtime role/preset editing (issue #3, C1).';



CREATE OR REPLACE FUNCTION "public"."is_platform_owner"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_email text;
begin
  -- Resolve email from auth.users (the authoritative identity store).
  select lower(trim(email)) into v_email
  from auth.users
  where id = p_user_id;

  -- Fail-closed: no auth row or no email => not an owner.
  if v_email is null or v_email = '' then
    return false;
  end if;

  -- Canonical owner emails (mirrors supabase/functions/_shared/auth.ts OWNER_EMAILS).
  return v_email in (
    'don.squires@firstsecurity.co.nz',
    'squires.don@live.com',
    'squires.don@gmail.com'
  );
end;
$$;


ALTER FUNCTION "public"."is_platform_owner"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_platform_owner"("p_user_id" "uuid") IS 'Returns true iff the given user_profiles.id resolves to a platform-owner email in auth.users. Fail-closed: no auth row or no email => false. Mirrors OWNER_EMAILS from supabase/functions/_shared/auth.ts.';



CREATE OR REPLACE FUNCTION "public"."is_zone_closed"("p_zone_id" "uuid", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  select jsonb_build_object(
    'closed',       true,
    'closure_id',   c.id,
    'closure_type', c.closure_type,
    'reason',       c.reason,
    'effective_from', c.effective_from,
    'effective_to',   c.effective_to
  )
  from zone_closures c
  where c.zone_id = p_zone_id
    and c.status <> 'lifted'
    and c.effective_from <= (p_at at time zone 'Pacific/Auckland')::date
    and (c.effective_to is null
         or c.effective_to >= (p_at at time zone 'Pacific/Auckland')::date)
  order by
    case c.closure_type
      when 'prohibited' then 0
      when 'restricted' then 1
      else 2
    end asc,
    c.effective_from desc
  limit 1;
$$;


ALTER FUNCTION "public"."is_zone_closed"("p_zone_id" "uuid", "p_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_zone_closed"("p_zone_id" "uuid", "p_at" timestamp with time zone) IS 'Returns the in-force closure for a zone at p_at as JSON (closed, closure_id, closure_type, reason, dates), or NULL when the zone is open. prohibited > restricted > temporary_closure. Dates compared in Pacific/Auckland.';



CREATE OR REPLACE FUNCTION "public"."log_bob_signing_event"("p_event_type" "text", "p_fingerprint_sha256" "text", "p_success" boolean, "p_reason" "text" DEFAULT NULL::"text", "p_request_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_identity_id uuid;
  v_event_id uuid;
  v_payload jsonb;
begin
  if p_event_type not in ('sign_request','sign_success','sign_failure','identity_check') then
    raise exception 'invalid event_type';
  end if;

  if p_fingerprint_sha256 is distinct from 'SHA256:ckUO3+2YpwZcGZFGvqu/R4cZpO1iXq8IaAL9pKQl3Y4' then
    raise exception 'fingerprint not allowlisted';
  end if;

  select id
  into v_identity_id
  from public.bob_signing_identities
  where provider = 'gitea'
    and key_name = 'bob-gitea'
    and fingerprint_sha256 = p_fingerprint_sha256
    and enabled = true
  order by created_at desc
  limit 1;

  if v_identity_id is null then
    raise exception 'active signing identity not found';
  end if;

  v_payload := jsonb_build_object(
    'namespace', 'gitea',
    'key_name', 'bob-gitea',
    'fingerprint_sha256', p_fingerprint_sha256,
    'success', p_success,
    'reason', p_reason,
    'request_id', p_request_id
  );

  insert into public.bob_signing_audit (
    identity_id,
    event_type,
    event_payload,
    actor_user_id
  )
  values (
    v_identity_id,
    p_event_type,
    v_payload,
    auth.uid()
  )
  returning id into v_event_id;

  return v_event_id;
end;
$$;


ALTER FUNCTION "public"."log_bob_signing_event"("p_event_type" "text", "p_fingerprint_sha256" "text", "p_success" boolean, "p_reason" "text", "p_request_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_entitled_org_ids"() RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public._entitled_org_ids_for(auth.uid());
$$;


ALTER FUNCTION "public"."my_entitled_org_ids"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."my_entitled_org_ids"() IS 'Set-returning resolver: org ids the CURRENT user (auth.uid()) is entitled to see. Self-only (no user param) - the impersonation-safe UI primitive. Delegates to _entitled_org_ids_for(auth.uid()); behaviour identical to 0352. Safety contract: o IN my_entitled_org_ids() IFF org_access_allowed(o). Granted to authenticated. #264.';



CREATE OR REPLACE FUNCTION "public"."my_entitled_org_ids_for_user"("p_user_id" "uuid") RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public._entitled_org_ids_for(p_user_id);
$$;


ALTER FUNCTION "public"."my_entitled_org_ids_for_user"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."my_entitled_org_ids_for_user"("p_user_id" "uuid") IS 'SERVICE-ROLE ONLY entitlement resolver for an EXPLICIT user id. Same set as my_entitled_org_ids() would return for that user (shared _entitled_org_ids_for). For back-end callers with no user JWT (the Bob conductor admin client, #306). REVOKED from public/authenticated/anon and granted to service_role ONLY - a user JWT cannot call it, so it is NOT an impersonation surface. Mirrors the 0125 bob_execute_read_query grant pattern.';



CREATE OR REPLACE FUNCTION "public"."notify_dispatch_job_created"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.status in ('pending', 'dispatched') then
    perform public.enqueue_notification(
      p_organization_id   => new.organization_id,
      p_category          => 'dispatch',
      p_title             => 'New dispatch job',
      p_body              => 'A new dispatch job is available.',
      p_severity          => case when new.priority in ('critical', 'high') then 'warning' else 'info' end,
      p_recipient_user_id => null,
      p_recipient_role    => 'officer',
      p_link_page         => 'open-jobs',
      p_link_payload      => jsonb_build_object('dispatch_job_id', new.id),
      p_dedup_key         => 'dispatch_job_open:' || new.id::text
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_dispatch_job_created"() OWNER TO "postgres";


