CREATE OR REPLACE FUNCTION "public"."patrol_stop_coords"("p_shift_id" "uuid") RETURNS TABLE("stop_id" "uuid", "site_id" "uuid", "zone_id" "uuid", "lat" double precision, "lng" double precision, "place_type" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  select
    ss.id as stop_id,
    ss.site_id,
    ss.zone_id,
    case
      when ss.site_id is not null then cs.gps_lat
      when ss.zone_id is not null then st_y(lz.center_point::geometry)
      else null
    end as lat,
    case
      when ss.site_id is not null then cs.gps_lng
      when ss.zone_id is not null then st_x(lz.center_point::geometry)
      else null
    end as lng,
    case
      when ss.site_id is not null then 'site'
      when ss.zone_id is not null then 'zone'
      else 'unknown'
    end as place_type
  from public.shift_stops ss
  left join public.client_sites   cs on cs.id = ss.site_id
  left join public.location_zones lz on lz.id = ss.zone_id
  where ss.shift_id = p_shift_id
    and ss.status in ('pending', 'en_route')
  order by ss.stop_order;
$$;


ALTER FUNCTION "public"."patrol_stop_coords"("p_shift_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."patrol_stop_coords"("p_shift_id" "uuid") IS 'Resolves each pending/en_route shift stop coordinate to plain lat/lng regardless of place type: site_id -> client_sites.gps_*, zone_id -> ST_Y/ST_X(location_zones.center_point). Unified stop model (!709); lets the patrol engine read zone-stops (which client_sites!inner previously dropped).';



CREATE OR REPLACE FUNCTION "public"."patrol_stop_module_keys"("p_stop_id" "uuid") RETURNS SETOF "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  select module_key
  from public.shift_stop_modules
  where shift_stop_id = p_stop_id
  order by module_key;
$$;


ALTER FUNCTION "public"."patrol_stop_module_keys"("p_stop_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."patrol_stop_module_keys"("p_stop_id" "uuid") IS 'Returns the module_key list for a shift stop from shift_stop_modules (canonical many-modules-per-stop, unified stop model !709). The engine/solver should carry all of these, not just the legacy singular shift_stops.module_key.';



CREATE OR REPLACE FUNCTION "public"."point_in_zone"("p_lat" double precision, "p_lng" double precision, "p_zone_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
  v_point geometry := st_setsrid(st_point(p_lng, p_lat), 4326);
begin
  return exists (
    select 1 from location_zones
    where id = p_zone_id
      and st_contains(boundary, v_point)
  );
end;
$$;


ALTER FUNCTION "public"."point_in_zone"("p_lat" double precision, "p_lng" double precision, "p_zone_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promote_document_to_reference_library"("p_document_version_id" "uuid", "p_target_scope" "text", "p_approver_id" "uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_doc_id uuid;
  v_org_id uuid;
  v_class record;
  v_title text := nullif(btrim(coalesce(p_metadata->>'title', '')), '');
  v_publisher text := nullif(btrim(coalesce(p_metadata->>'publisher', '')), '');
  v_doc_type text := nullif(btrim(coalesce(p_metadata->>'document_type', '')), '');
  v_effective text := coalesce(p_metadata->>'effective_from', p_metadata->>'version_label');
  v_is_global boolean := (p_target_scope = 'global_reference');
  v_entry_id uuid;
begin
  if p_target_scope not in ('global_reference','tenant_reference') then
    return jsonb_build_object('ok', false, 'error', 'target_scope must be global_reference or tenant_reference');
  end if;

  select dv.document_id, d.organization_id
  into v_doc_id, v_org_id
  from public.document_versions dv
  join public.documents d on d.id = dv.document_id
  where dv.id = p_document_version_id;

  if v_doc_id is null then
    return jsonb_build_object('ok', false, 'error', 'document_version not found');
  end if;

  -- Latest classification is required before any promotion.
  select * into v_class
  from public.document_classifications
  where document_version_id = p_document_version_id
  order by created_at desc
  limit 1;

  if v_class is null then
    return jsonb_build_object('ok', false, 'error', 'document must be classified before promotion');
  end if;

  -- HARD routing rules for global promotion.
  if v_is_global then
    if v_class.privacy_class not in ('public','internal_non_sensitive') then
      return jsonb_build_object('ok', false, 'error',
        format('privacy_class %s is not eligible for global reference; tenant-scope only', v_class.privacy_class));
    end if;
    if v_class.contains_pii or v_class.contains_financial_data or v_class.contains_legal_privilege then
      return jsonb_build_object('ok', false, 'error', 'document flagged PII/financial/legal-privilege; global promotion blocked');
    end if;
    -- Require human review OR confident, unambiguous classification.
    if v_class.classifier_source <> 'human_review'
       and coalesce(v_class.confidence, 0) < 0.85 then
      return jsonb_build_object('ok', false, 'error', 'low-confidence classification requires human review before global promotion');
    end if;
    -- Provenance floor for durable global references.
    if v_title is null or v_publisher is null or v_doc_type is null or v_effective is null then
      return jsonb_build_object('ok', false, 'error', 'global promotion requires title, publisher, document_type and effective date/version');
    end if;
  end if;

  -- Physical bytes stay put; routing is logical (update scope + catalogue).
  update public.documents
  set current_scope = case when v_is_global then 'global_reference' else 'tenant' end
  where id = v_doc_id;

  insert into public.reference_catalog_entries (
    document_version_id, organization_id, title, topic, publisher, jurisdiction,
    document_type, trust_level, searchable_tags, is_global_reference,
    approval_status, approved_by, approved_at
  ) values (
    p_document_version_id,
    case when v_is_global then null else v_org_id end,
    coalesce(v_title, 'Untitled document'),
    p_metadata->>'topic',
    v_publisher,
    p_metadata->>'jurisdiction',
    v_doc_type,
    coalesce(nullif(p_metadata->>'trust_level',''), 'provisional'),
    coalesce((select array_agg(value::text) from jsonb_array_elements_text(coalesce(p_metadata->'searchable_tags','[]'::jsonb))), '{}'),
    v_is_global,
    'approved',
    p_approver_id,
    now()
  )
  returning id into v_entry_id;

  return jsonb_build_object(
    'ok', true,
    'catalog_entry_id', v_entry_id,
    'target_scope', p_target_scope,
    'is_global_reference', v_is_global,
    'privacy_class', v_class.privacy_class
  );
exception when others then
  return jsonb_build_object('ok', false, 'error', sqlerrm);
end;
$$;


ALTER FUNCTION "public"."promote_document_to_reference_library"("p_document_version_id" "uuid", "p_target_scope" "text", "p_approver_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."promote_document_to_reference_library"("p_document_version_id" "uuid", "p_target_scope" "text", "p_approver_id" "uuid", "p_metadata" "jsonb") IS 'Governed promotion of a classified document version to the tenant or global reference library. Hard-rejects global promotion of tenant_sensitive/restricted, PII/financial/legal-privilege, low-confidence/unreviewed, or under-provenanced material. service_role execute only; the edge function verifies the approver is admin/GM first.';



CREATE OR REPLACE FUNCTION "public"."record_sla_arrival"("p_clock_id" "uuid", "p_arrived_at" timestamp with time zone DEFAULT "now"()) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_clock   sla_clocks%rowtype;
  v_elapsed integer;
  v_status  text;
begin
  select * into v_clock from sla_clocks where id = p_clock_id;
  if not found then
    raise exception 'SLA clock not found';
  end if;
  if not org_access_allowed(v_clock.organization_id) then
    raise exception 'Access denied';
  end if;

  v_elapsed := ceil(extract(epoch from (p_arrived_at - v_clock.started_at)) / 60.0);

  if v_clock.target_minutes is null then
    v_status := 'met'; -- no target = informational only
  elsif v_elapsed <= v_clock.target_minutes then
    v_status := 'met';
  else
    v_status := 'breached';
  end if;

  update sla_clocks
  set arrived_at      = p_arrived_at,
      elapsed_minutes = v_elapsed,
      status          = v_status,
      updated_at      = now()
  where id = p_clock_id;

  return v_status;
end;
$$;


ALTER FUNCTION "public"."record_sla_arrival"("p_clock_id" "uuid", "p_arrived_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_sla_arrival"("p_clock_id" "uuid", "p_arrived_at" timestamp with time zone) IS 'Stops an SLA clock at arrival, computes elapsed minutes, records met/breached vs target_minutes, and returns the resulting status.';



CREATE OR REPLACE FUNCTION "public"."refresh_canonical_ta_names"("p_names" "text"[], "p_source" "text" DEFAULT 'nzta_featureserver'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_count integer;
  v_name text;
BEGIN
  -- Guard: never wipe the table with an empty input (Q6 ruling)
  IF p_names IS NULL OR array_length(p_names, 1) IS NULL OR array_length(p_names, 1) = 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'REFRESH_REFUSED: input names array is empty. The NZTA source may be unavailable. The existing canonical_ta_names data has been preserved (Q6: never silently degrade).'
    );
  END IF;

  -- Upsert each name
  v_count := 0;
  FOREACH v_name IN ARRAY p_names LOOP
    INSERT INTO public.canonical_ta_names (ta_name, source, last_refreshed_at)
    VALUES (trim(v_name), p_source, now())
    ON CONFLICT (ta_name) DO UPDATE
      SET source = EXCLUDED.source,
          last_refreshed_at = EXCLUDED.last_refreshed_at;
    v_count := v_count + 1;
  END LOOP;

  -- Remove names that are no longer in the authoritative source
  -- (but only if we received a reasonable number of names -- at least 50
  -- to avoid accidental wipe from a partial fetch)
  IF v_count >= 50 THEN
    DELETE FROM public.canonical_ta_names
    WHERE ta_name NOT IN (SELECT unnest(p_names));
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'upserted', v_count,
    'source', p_source,
    'refreshed_at', now()
  );
END;
$$;


ALTER FUNCTION "public"."refresh_canonical_ta_names"("p_names" "text"[], "p_source" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refresh_canonical_ta_names"("p_names" "text"[], "p_source" "text") IS 'Upsert canonical TA names from a live NZTA fetch. Called by the bob-refresh-canonical-ta-names edge function. Refuses empty input (Q6: never silently degrade). Phase 2 geofence redesign (epic #226).';



CREATE OR REPLACE FUNCTION "public"."resolve_access_basis"("p_user" "uuid" DEFAULT "auth"."uid"(), "p_observation_id" "uuid" DEFAULT NULL::"uuid", "p_noise_assessment_id" "uuid" DEFAULT NULL::"uuid", "p_smoke_assessment_id" "uuid" DEFAULT NULL::"uuid", "p_biosecurity_assessment_id" "uuid" DEFAULT NULL::"uuid", "p_incident_id" "uuid" DEFAULT NULL::"uuid", "p_notice_id" "uuid" DEFAULT NULL::"uuid", "p_enforcement_case_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ref_count      int;
  v_caller         uuid := auth.uid();
  v_basis          text := null;
  v_expiry         text := null;
begin
  -- ========================================================
  -- 0329 IDENTITY GUARD (SELF-ONLY). Server-derived caller; reject any request
  -- to resolve someone else's basis. This is the ONLY change from the 0327
  -- body; every basis branch below is reproduced verbatim.
  --
  -- p_user defaults to auth.uid() (UI sends no id). If a caller explicitly
  -- passes a p_user that is not themselves, or is unauthenticated, resolve to
  -- NO basis -- an informative, content-free statement (reject by
  -- non-appearance, never an error that would itself confirm anything).
  -- ========================================================
  if v_caller is null or p_user is null or p_user <> v_caller then
    return jsonb_build_object(
      'decision_state',       'no_task_entitlement',
      'granted_basis',        null,
      'failed_gate',          'task',
      'expiry_end_condition', null,
      'sensitivity_mode',     'informative',
      'message_key',          'access.no_live_basis'
    );
  end if;

  -- COMPOSITION CONTRACT (ACCESS_MODEL.md section 7): this resolver returns on
  -- the FIRST basis found, and the branch order below IS the composition rule -
  -- strongest depth first (ownership -> dispatch on-scene -> dispatch en-route
  -- -> roster -> supervisory), so "first match" == "maximum depth". This
  -- ordering is LOAD-BEARING: do not reorder without switching to an explicit
  -- resolve-all-then-take-max-depth form, or a weaker basis could shadow a
  -- stronger one and under-grant (a lockout).
  -- Exactly-one-record guard (mirrors task_assignments chk_one_record).
  v_ref_count :=
      (case when p_observation_id            is not null then 1 else 0 end)
    + (case when p_noise_assessment_id       is not null then 1 else 0 end)
    + (case when p_smoke_assessment_id       is not null then 1 else 0 end)
    + (case when p_biosecurity_assessment_id is not null then 1 else 0 end)
    + (case when p_incident_id               is not null then 1 else 0 end)
    + (case when p_notice_id                 is not null then 1 else 0 end)
    + (case when p_enforcement_case_id       is not null then 1 else 0 end);

  if v_ref_count <> 1 then
    -- Malformed call: no basis. (section 0: absent basis, not a verdict.)
    return jsonb_build_object(
      'decision_state',       'no_task_entitlement',
      'granted_basis',        null,
      'failed_gate',          'task',
      'expiry_end_condition', null,
      'sensitivity_mode',     'informative',
      'message_key',          'access.no_live_basis'
    );
  end if;

  -- ========================================================
  -- OWNERSHIP-DERIVED bases (task_assignments 0323; geofence NOT required).
  -- follow_up_ownership + direct_module_initiation resolve FULL depth.
  -- A live row with ended_at IS NULL is a LIVE basis.
  -- ========================================================
  select ta.basis,
         'basis_ends: ' || coalesce(ta.end_reason, 'live until ended_at set')
    into v_basis, v_expiry
  from public.task_assignments ta
  where ta.user_id = p_user
    and ta.ended_at is null
    and (
         (p_observation_id            is not null and ta.observation_id            = p_observation_id)
      or (p_noise_assessment_id       is not null and ta.noise_assessment_id       = p_noise_assessment_id)
      or (p_smoke_assessment_id       is not null and ta.smoke_assessment_id       = p_smoke_assessment_id)
      or (p_biosecurity_assessment_id is not null and ta.biosecurity_assessment_id = p_biosecurity_assessment_id)
      or (p_incident_id               is not null and ta.incident_id               = p_incident_id)
      or (p_notice_id                 is not null and ta.notice_id                 = p_notice_id)
      or (p_enforcement_case_id       is not null and ta.enforcement_case_id       = p_enforcement_case_id)
    )
    -- Prefer the strongest ownership basis first (follow_up/initiation = full;
    -- backup graduates and is handled in the presence block for its depth).
    order by case ta.basis
               when 'follow_up_ownership'       then 1
               when 'direct_module_initiation'  then 2
               when 'backup_attachment'         then 3
               else 4 end
    limit 1;

  if v_basis in ('follow_up_ownership', 'direct_module_initiation') then
    -- Ownership-derived: FULL working depth (section 3: geofence may be false;
    -- report writing / QA / handover must not break). S12 no-lockout case.
    return jsonb_build_object(
      'decision_state',       'full_access',
      'granted_basis',        v_basis,
      'failed_gate',          'none',
      'expiry_end_condition', v_expiry,
      'sensitivity_mode',     'informative',
      'message_key',          'access.granted.' || v_basis
    );
  elsif v_basis = 'backup_attachment' then
    -- R1: backup graduates. Without a live-geofence gate in v1, the task record
    -- itself is the presence proof; a live backup attachment earns operational
    -- depth (on-scene upgrade is a v-next hardening, ACCESS_MODEL section 3).
    return jsonb_build_object(
      'decision_state',       'operational_only',
      'granted_basis',        'backup_attachment',
      'failed_gate',          'none',
      'expiry_end_condition', v_expiry,
      'sensitivity_mode',     'informative',
      'message_key',          'access.granted.backup_attachment'
    );
  end if;

  -- ========================================================
  -- PRESENCE-DERIVED: dispatch_response (TIMESTAMP-LED graduation, S3/S13).
  -- Officer link: dispatch_jobs.dispatch_resource_id
  --   -> dispatch_resources.assigned_officer_id (live-verified path).
  -- Depth: dispatched_at set -> operational_only (en route);
  --        on_scene_at set   -> full_access (arrived).
  -- 0327 PLACE-LINK (Bug 2 fix): the dispatch job must be for the SAME SITE as
  -- the observation -- dj.client_site_id = o.site_id (the only place pair
  -- anchored in the live schema at both ends). FAIL-CLOSED: an observation with
  -- no site_id gets no dispatch basis (the join cannot match a null).
  -- ========================================================
  if p_observation_id is not null then
    perform 1
      from public.dispatch_jobs dj
      join public.dispatch_resources dr on dr.id = dj.dispatch_resource_id
      join public.observations o on o.id = p_observation_id
     where dr.assigned_officer_id = p_user
       and dj.dispatched_at is not null
       and dj.completed_at is null
       and dj.on_scene_at is not null
       and o.site_id is not null
       and dj.client_site_id = o.site_id;
    if found then
      return jsonb_build_object(
        'decision_state',       'full_access',
        'granted_basis',        'dispatch_response',
        'failed_gate',          'none',
        'expiry_end_condition', 'basis_ends: dispatch completed_at set, reassignment, or 24h grace (Q1)',
        'sensitivity_mode',     'informative',
        'message_key',          'access.granted.dispatch_response.on_scene'
      );
    end if;

    perform 1
      from public.dispatch_jobs dj
      join public.dispatch_resources dr on dr.id = dj.dispatch_resource_id
      join public.observations o on o.id = p_observation_id
     where dr.assigned_officer_id = p_user
       and dj.dispatched_at is not null
       and dj.completed_at is null
       and o.site_id is not null
       and dj.client_site_id = o.site_id;
    if found then
      -- En route (dispatched, not yet on-scene): operational_only (S13/S3).
      return jsonb_build_object(
        'decision_state',       'operational_only',
        'granted_basis',        'dispatch_response',
        'failed_gate',          'none',
        'expiry_end_condition', 'basis_ends: dispatch completed_at set, reassignment, or 24h grace (Q1)',
        'sensitivity_mode',     'informative',
        'message_key',          'access.granted.dispatch_response.en_route'
      );
    end if;
  end if;

  -- ========================================================
  -- PRESENCE-DERIVED: rostered_presence.
  -- Officer link: shift_stops JOIN shifts (shifts.officer_user_id) - shift_stops
  -- has NO direct officer column (live-verified; the substrate-note trap).
  -- Live presence = a non-terminal stop (status not in the done set).
  -- Depth: presence-alone caps at operational_only (section 7 composition, S11).
  -- v1: the roster record is the presence proof (geofence deferred).
  -- ========================================================
  if p_observation_id is not null then
    perform 1
      from public.shift_stops ss
      join public.shifts s on s.id = ss.shift_id
      join public.observations o on o.id = p_observation_id
     where s.officer_user_id = p_user
       and ss.status not in ('completed', 'skipped', 'cancelled')
       and (
              (ss.site_id is not null and ss.site_id = o.site_id)
           or (ss.zone_id is not null and ss.zone_id = o.zone_id)
       );
    if found then
      -- S11: inside the tasked place, presence basis -> operational_only, NEVER
      -- narrative history from presence alone.
      return jsonb_build_object(
        'decision_state',       'operational_only',
        'granted_basis',        'rostered_presence',
        'failed_gate',          'none',
        'expiry_end_condition', 'basis_ends: stop completed/skipped/cancelled or shift end',
        'sensitivity_mode',     'informative',
        'message_key',          'access.granted.rostered_presence'
      );
    end if;
  end if;

  -- ========================================================
  -- PRESENCE/RESPONSIBILITY: supervisory_review (R2 scoped default).
  -- staff_reporting: this user is the reports_to for an officer who holds a live
  -- task basis on THIS record; active line = effective_to IS NULL.
  -- Default depth (sensitive subject-matter): operational_only (R2). The
  -- officer-SAFETY inversion (full_access) is NOT auto-resolved here - it is a
  -- named, record-bound escalation basis (R2 exception / S10), reserved for the
  -- welfare/duress path, never a broad supervisor read.
  -- ========================================================
  perform 1
    from public.staff_reporting sr
    join public.task_assignments ta on ta.user_id = sr.user_id and ta.ended_at is null
   where sr.reports_to_user_id = p_user
     and sr.effective_to is null
     and (
           (p_observation_id            is not null and ta.observation_id            = p_observation_id)
        or (p_noise_assessment_id       is not null and ta.noise_assessment_id       = p_noise_assessment_id)
        or (p_smoke_assessment_id       is not null and ta.smoke_assessment_id       = p_smoke_assessment_id)
        or (p_biosecurity_assessment_id is not null and ta.biosecurity_assessment_id = p_biosecurity_assessment_id)
        or (p_incident_id               is not null and ta.incident_id               = p_incident_id)
        or (p_notice_id                 is not null and ta.notice_id                 = p_notice_id)
        or (p_enforcement_case_id       is not null and ta.enforcement_case_id       = p_enforcement_case_id)
     );
  if found then
    return jsonb_build_object(
      'decision_state',       'operational_only',
      'granted_basis',        'supervisory_review',
      'failed_gate',          'none',
      'expiry_end_condition', 'basis_ends: reporting responsibility ends or supervised task ends (R2)',
      'sensitivity_mode',     'informative',
      'message_key',          'access.granted.supervisory_review'
    );
  end if;

  -- ========================================================
  -- No live task basis found. section 0: this is ABSENT BASIS, not a verdict on
  -- the reader. operator_custody + lawful_production are SEPARATE named bases,
  -- resolved elsewhere (R3) - deliberately NOT granted here.
  -- ========================================================
  return jsonb_build_object(
    'decision_state',       'no_task_entitlement',
    'granted_basis',        null,
    'failed_gate',          'task',
    'expiry_end_condition', null,
    'sensitivity_mode',     'informative',
    'message_key',          'access.no_live_basis'
  );
end;
$$;


ALTER FUNCTION "public"."resolve_access_basis"("p_user" "uuid", "p_observation_id" "uuid", "p_noise_assessment_id" "uuid", "p_smoke_assessment_id" "uuid", "p_biosecurity_assessment_id" "uuid", "p_incident_id" "uuid", "p_notice_id" "uuid", "p_enforcement_case_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_access_basis"("p_user" "uuid", "p_observation_id" "uuid", "p_noise_assessment_id" "uuid", "p_smoke_assessment_id" "uuid", "p_biosecurity_assessment_id" "uuid", "p_incident_id" "uuid", "p_notice_id" "uuid", "p_enforcement_case_id" "uuid") IS 'BASIS ENGINE (ACCESS_MODEL.md sections 8/11). SECURITY DEFINER + fixed search_path (0326). 0327: dispatch branch SITE-ANCHORED. 0329: SELF-ONLY - p_user defaults to auth.uid() and any p_user <> auth.uid() (or unauthenticated) resolves to no-basis. Closes the caller-supplied-identity impersonation surface on the direct-RPC / UI path. No supervisor/GM cross-user carve-out (separate privileged path if ever needed). Narrow contract: one SELF user, one record, verdict only.';



CREATE OR REPLACE FUNCTION "public"."resolve_access_basis_batch"("p_observation_ids" "uuid"[]) RETURNS SETOF "public"."access_basis_verdict"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller uuid := auth.uid();
  v_count  int  := coalesce(array_length(p_observation_ids, 1), 0);
begin
  -- ========================================================
  -- INPUT CAP: hard cap of 200 ids per call. Over-cap -> reject the whole
  -- call. Do NOT silently truncate. Prevents the batch becoming a
  -- bulk-enumeration primitive.
  -- ========================================================
  if v_count > 200 then
    raise exception 'resolve_access_basis_batch: input cap exceeded (% ids, max 200)', v_count;
  end if;

  -- ========================================================
  -- SELF-ONLY: unauthenticated caller -> every id gets the collapsed
  -- no-basis verdict. There is NO p_user parameter at all; the caller
  -- identity is derived server-side from auth.uid() only.
  -- ========================================================
  if v_caller is null then
    return query
      select
        req.id,
        'no_task_entitlement'::text,
        null::text,
        'task'::text,
        null::text,
        'informative'::text,
        'access.no_live_basis'::text
      from unnest(p_observation_ids) as req(id);
    return;
  end if;

  -- ========================================================
  -- BATCHED BASIS DERIVATION
  -- Mirrors 0329 branches and ordering per id, applied set-wise.
  -- Composition order (first-match-by-depth, strongest first):
  --   1. ownership (follow_up_ownership / direct_module_initiation) -> full
  --   2. backup_attachment -> operational_only
  --   3. dispatch on-scene -> full_access
  --   4. dispatch en-route -> operational_only
  --   5. rostered_presence -> operational_only
  --   6. supervisory_review -> operational_only
  --
  -- The CTE chain resolves ALL matching bases per id, ranks them by the
  -- same depth ordering as 0329, and picks the strongest (first match).
  -- Any requested id with no match gets the collapsed no-basis verdict
  -- via LEFT JOIN against the input array (EXISTENCE COLLAPSE).
  -- ========================================================
  return query
  with
    -- Unnest the input array into a relation for joining.
    requested as (
      select unnest(p_observation_ids) as obs_id
    ),

    -- BRANCH 1: ownership-derived bases (task_assignments).
    -- follow_up_ownership / direct_module_initiation -> full_access (depth 1,2)
    -- backup_attachment -> operational_only (depth 3)
    -- Mirrors 0329 ownership block verbatim.
    ownership as (
      select distinct on (ta.observation_id)
        ta.observation_id as obs_id,
        ta.basis,
        'basis_ends: ' || coalesce(ta.end_reason, 'live until ended_at set') as expiry
      from public.task_assignments ta
      join requested r on r.obs_id = ta.observation_id
      where ta.user_id = v_caller
        and ta.ended_at is null
        and ta.observation_id is not null
      order by ta.observation_id,
        case ta.basis
          when 'follow_up_ownership'      then 1
          when 'direct_module_initiation' then 2
          when 'backup_attachment'        then 3
          else 4
        end
    ),

    -- BRANCH 2: dispatch on-scene (full_access).
    -- 0327 site-anchored: dj.client_site_id = o.site_id.
    -- Mirrors 0329 dispatch on-scene block verbatim.
    dispatch_on_scene as (
      select distinct on (o.id)
        o.id as obs_id
      from public.observations o
      join requested r on r.obs_id = o.id
      join public.dispatch_jobs dj on dj.client_site_id = o.site_id
      join public.dispatch_resources dr on dr.id = dj.dispatch_resource_id
      where dr.assigned_officer_id = v_caller
        and dj.dispatched_at is not null
        and dj.completed_at is null
        and dj.on_scene_at is not null
        and o.site_id is not null
    ),

    -- BRANCH 3: dispatch en-route (operational_only).
    -- Same join as on-scene but WITHOUT on_scene_at requirement.
    -- Exclude ids already matched by on-scene (first-match-by-depth).
    dispatch_en_route as (
      select distinct on (o.id)
        o.id as obs_id
      from public.observations o
      join requested r on r.obs_id = o.id
      join public.dispatch_jobs dj on dj.client_site_id = o.site_id
      join public.dispatch_resources dr on dr.id = dj.dispatch_resource_id
      where dr.assigned_officer_id = v_caller
        and dj.dispatched_at is not null
        and dj.completed_at is null
        and o.site_id is not null
        and o.id not in (select dos.obs_id from dispatch_on_scene dos)
    ),

    -- BRANCH 4: rostered_presence (operational_only).
    -- Officer link: shift_stops -> shifts.officer_user_id.
    -- Mirrors 0329 roster block verbatim.
    roster as (
      select distinct on (o.id)
        o.id as obs_id
      from public.observations o
      join requested r on r.obs_id = o.id
      join public.shift_stops ss on (
           (ss.site_id is not null and ss.site_id = o.site_id)
        or (ss.zone_id is not null and ss.zone_id = o.zone_id)
      )
      join public.shifts s on s.id = ss.shift_id
      where s.officer_user_id = v_caller
        and ss.status not in ('completed', 'skipped', 'cancelled')
    ),

    -- BRANCH 5: supervisory_review (operational_only).
    -- staff_reporting: caller is reports_to for an officer who holds a live
    -- task basis on this observation. Mirrors 0329 supervisory block.
    supervisory as (
      select distinct on (ta.observation_id)
        ta.observation_id as obs_id
      from public.staff_reporting sr
      join public.task_assignments ta
        on ta.user_id = sr.user_id
        and ta.ended_at is null
        and ta.observation_id is not null
      join requested r on r.obs_id = ta.observation_id
      where sr.reports_to_user_id = v_caller
        and sr.effective_to is null
    ),

    -- COMPOSE: first-match-by-depth per id. The COALESCE chain mirrors the
    -- 0329 branch ordering: ownership > dispatch on-scene > dispatch en-route
    -- > roster > supervisory. For each id, the first non-null match wins.
    resolved as (
      select
        r.obs_id,
        -- Decision state: full_access or operational_only depending on basis.
        case
          when ow.basis in ('follow_up_ownership', 'direct_module_initiation') then 'full_access'
          when ow.basis = 'backup_attachment' then 'operational_only'
          when dos.obs_id is not null then 'full_access'
          when der.obs_id is not null then 'operational_only'
          when ros.obs_id is not null then 'operational_only'
          when sup.obs_id is not null then 'operational_only'
          else null  -- no basis found
        end as decision_state,
        -- Granted basis name.
        case
          when ow.basis is not null then ow.basis
          when dos.obs_id is not null then 'dispatch_response'
          when der.obs_id is not null then 'dispatch_response'
          when ros.obs_id is not null then 'rostered_presence'
          when sup.obs_id is not null then 'supervisory_review'
          else null
        end as granted_basis,
        -- Expiry end condition.
        case
          when ow.basis is not null then ow.expiry
          when dos.obs_id is not null then 'basis_ends: dispatch completed_at set, reassignment, or 24h grace (Q1)'
          when der.obs_id is not null then 'basis_ends: dispatch completed_at set, reassignment, or 24h grace (Q1)'
          when ros.obs_id is not null then 'basis_ends: stop completed/skipped/cancelled or shift end'
          when sup.obs_id is not null then 'basis_ends: reporting responsibility ends or supervised task ends (R2)'
          else null
        end as expiry_end_condition,
        -- Message key.
        case
          when ow.basis in ('follow_up_ownership', 'direct_module_initiation')
            then 'access.granted.' || ow.basis
          when ow.basis = 'backup_attachment'
            then 'access.granted.backup_attachment'
          when dos.obs_id is not null then 'access.granted.dispatch_response.on_scene'
          when der.obs_id is not null then 'access.granted.dispatch_response.en_route'
          when ros.obs_id is not null then 'access.granted.rostered_presence'
          when sup.obs_id is not null then 'access.granted.supervisory_review'
          else null
        end as message_key
      from requested r
      left join ownership ow on ow.obs_id = r.obs_id
      left join dispatch_on_scene dos on dos.obs_id = r.obs_id
      left join dispatch_en_route der on der.obs_id = r.obs_id
      left join roster ros on ros.obs_id = r.obs_id
      left join supervisory sup on sup.obs_id = r.obs_id
    )

  -- FINAL SELECT: one row per requested id. EXISTENCE COLLAPSE: ids with
  -- no basis (including nonexistent ids that never matched any join) get
  -- the identical no-basis verdict via COALESCE.
  select
    rv.obs_id                                                          as id,
    coalesce(rv.decision_state, 'no_task_entitlement')                 as decision_state,
    rv.granted_basis                                                   as granted_basis,
    case when rv.decision_state is not null then 'none' else 'task' end as failed_gate,
    rv.expiry_end_condition                                            as expiry_end_condition,
    'informative'::text                                                as sensitivity_mode,
    coalesce(rv.message_key, 'access.no_live_basis')                   as message_key
  from resolved rv;
end;
$$;


ALTER FUNCTION "public"."resolve_access_basis_batch"("p_observation_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_access_basis_batch"("p_observation_ids" "uuid"[]) IS 'BATCHED BASIS ENGINE (ACCESS_MODEL.md sections 8/11, step-4 prerequisite). Ratified plan: docs/design/BATCHED_ACCESS_BASIS_RESOLVER.md (!1292). SECURITY DEFINER + fixed search_path. SELF-ONLY: caller derived from auth.uid(); NO p_user parameter. Observations-only (not the 7-type polymorphic batch). Returns one verdict row per requested id; existence collapsed (nonexistent/inaccessible/no-basis ids all yield the identical no-basis shape). Input cap: 200 ids. Static SQL only. Additive: does not touch the single-record resolver, the RLS boolean, or the keystone.';



CREATE OR REPLACE FUNCTION "public"."resolve_access_grants"("p_user_id" "uuid", "p_org_id" "uuid") RETURNS TABLE("area" "text", "level" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with rank_map as (
    select * from (values
      ('view', 1), ('verify', 2), ('approve', 3), ('adjust', 4), ('manage', 5)
    ) as r(level, ord)
  ),
  -- (a) direct per-user grants scoped to an org whose subtree contains p_org_id
  direct as (
    select g.area, g.level
    from public.staff_area_grants g
    where g.user_id = p_user_id
      and g.status = 'active'
      and p_org_id = any (public.get_descendant_organizations(g.scope_org_id))
  ),
  -- (b) grants from assigned presets, expanded from the jsonb grants map
  from_presets as (
    select kv.key as area, kv.value as level
    from public.preset_assignments pa
    join public.access_presets ap on ap.id = pa.preset_id
    cross join lateral jsonb_each_text(ap.grants) as kv(key, value)
    where pa.user_id = p_user_id
      and pa.status = 'active'
      and p_org_id = any (public.get_descendant_organizations(pa.scope_org_id))
  ),
  effective as (
    select area, level from direct
    union all
    select area, level from from_presets
  ),
  ranked as (
    select e.area, rm.ord
    from effective e
    join rank_map rm on rm.level = e.level
  ),
  best as (
    select area, max(ord) as ord from ranked group by area
  )
  select b.area, rm.level
  from best b
  join rank_map rm on rm.ord = b.ord
  order by b.area;
$$;


ALTER FUNCTION "public"."resolve_access_grants"("p_user_id" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_access_grants"("p_user_id" "uuid", "p_org_id" "uuid") IS 'Effective functional-area:level for a user in an org: union of direct grants (staff_area_grants) + assigned-preset grants (preset_assignments -> access_presets.grants), highest level per area. Preset edits cascade to all holders (issue #3, C3).';



CREATE OR REPLACE FUNCTION "public"."resolve_context"("p_lat" double precision, "p_lng" double precision, "p_org_id" "uuid", "p_module_key" "text" DEFAULT NULL::"text", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("in_operating_bounds" boolean, "out_of_bounds_district" "text", "governing_jurisdiction_id" "uuid", "governing_jurisdiction_name" "text", "on_site" boolean, "site_id" "uuid", "client_org_id" "uuid", "matched_zone_id" "uuid", "matched_module_key" "text", "effective_rules" "jsonb", "resolution_status" "text", "governor_overlap_flag" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_point        geometry := st_setsrid(st_point(p_lng, p_lat), 4326);
  v_in_bounds    boolean := false;
  v_oob_district text := null;
  v_jur_id       uuid := null;
  v_jur_name     text := null;
  v_zone         record;
  v_on_site      boolean := false;
  v_site_id      uuid := null;
  v_client_org   uuid := null;  -- final owner answer (always resolves TO THE HOUSE where possible)
  v_rules        jsonb := '{}'::jsonb;
  v_resolution   text := 'outside_all_geofences';
  v_gov_overlap  boolean := false;

  -- Layer 1/2 verification state
  v_org_jur_verification text;
  v_org_jur_geom_exists  boolean;
  v_org_jur_geom_valid   boolean;

  -- Governor count for overlap detection
  v_governor_count integer := 0;
BEGIN
  -- -- Layer 1: operating bounds --
  -- P1/P2: must distinguish no-geofence / unverified / invalid / outside / inside.
  SELECT
    o.jurisdiction_geom IS NOT NULL,
    CASE WHEN o.jurisdiction_geom IS NOT NULL
         THEN ST_IsValid(o.jurisdiction_geom) AND NOT ST_IsEmpty(o.jurisdiction_geom)
         ELSE false END,
    o.jurisdiction_verification,
    CASE WHEN o.jurisdiction_geom IS NOT NULL
              AND ST_IsValid(o.jurisdiction_geom)
              AND NOT ST_IsEmpty(o.jurisdiction_geom)
              AND o.jurisdiction_verification = 'verified'
         THEN st_contains(o.jurisdiction_geom, v_point)
         ELSE false END
    INTO v_org_jur_geom_exists, v_org_jur_geom_valid,
         v_org_jur_verification, v_in_bounds
  FROM public.organizations o
  WHERE o.id = p_org_id;

  -- Determine Layer 1 resolution_status contribution
  IF NOT COALESCE(v_org_jur_geom_exists, false) THEN
    v_resolution := 'unresolved_no_geofence';
  ELSIF NOT COALESCE(v_org_jur_geom_valid, false) THEN
    v_resolution := 'unresolved_invalid';
  ELSIF COALESCE(v_org_jur_verification, 'unverified') <> 'verified' THEN
    v_resolution := 'unresolved_unverified';
  ELSIF NOT COALESCE(v_in_bounds, false) THEN
    -- Verified geometry exists, point is outside
    v_resolution := 'outside_all_geofences';
  ELSE
    -- Point is inside verified jurisdiction; continue to Layer 2/3
    v_resolution := 'outside_all_geofences';
  END IF;

  v_in_bounds := COALESCE(v_in_bounds, false);

  IF NOT v_in_bounds THEN
    SELECT o.name INTO v_oob_district
    FROM public.organizations o
    WHERE o.jurisdiction_geom IS NOT NULL
      AND st_contains(o.jurisdiction_geom, v_point)
    ORDER BY st_area(o.jurisdiction_geom) ASC
    LIMIT 1;
  END IF;

  -- -- Layer 2: governing council jurisdiction (ROLE-AWARE) --
  -- (UNCHANGED from 0290 -- byte-identical.)

  -- First, count qualifying governors for overlap detection
  SELECT count(*)
    INTO v_governor_count
  FROM public.organizations o
  WHERE o.jurisdiction_geom IS NOT NULL
    AND o.id <> p_org_id
    AND o.jurisdiction_verification = 'verified'
    AND ST_IsValid(o.jurisdiction_geom)
    AND NOT ST_IsEmpty(o.jurisdiction_geom)
    AND st_contains(o.jurisdiction_geom, v_point)
    AND (
      EXISTS (
        SELECT 1 FROM public.org_engagements e
        WHERE e.status = 'active'
          AND ((e.from_org_id = p_org_id AND e.to_org_id = o.id)
            OR (e.to_org_id = p_org_id AND e.from_org_id = o.id))
      )
      OR o.parent_organization_id = p_org_id
      OR o.id = (SELECT parent_organization_id FROM public.organizations WHERE id = p_org_id)
    )
    AND (
      o.organization_type IN ('government', 'service_provider', 'branch')
      OR EXISTS (
        SELECT 1 FROM public.service_agreements sa
        WHERE sa.provider_organization_id = o.id
          AND (sa.ends_on IS NULL OR sa.ends_on >= current_date)
      )
      OR EXISTS (
        SELECT 1 FROM public.organizations child
        WHERE child.parent_organization_id = o.id
      )
      OR EXISTS (
        SELECT 1 FROM public.org_engagements e2
        WHERE e2.to_org_id = o.id
          AND e2.status = 'active'
      )
    );

  -- Flag overlap when more than one qualifying governor
  IF v_governor_count > 1 THEN
    v_gov_overlap := true;
  END IF;

  -- Pick the primary governor (smallest area among qualifying governors)
  SELECT o.id, o.name
    INTO v_jur_id, v_jur_name
  FROM public.organizations o
  WHERE o.jurisdiction_geom IS NOT NULL
    AND o.id <> p_org_id
    AND o.jurisdiction_verification = 'verified'
    AND ST_IsValid(o.jurisdiction_geom)
    AND NOT ST_IsEmpty(o.jurisdiction_geom)
    AND st_contains(o.jurisdiction_geom, v_point)
    AND (
      EXISTS (
        SELECT 1 FROM public.org_engagements e
        WHERE e.status = 'active'
          AND ((e.from_org_id = p_org_id AND e.to_org_id = o.id)
            OR (e.to_org_id = p_org_id AND e.from_org_id = o.id))
      )
      OR o.parent_organization_id = p_org_id
      OR o.id = (SELECT parent_organization_id FROM public.organizations WHERE id = p_org_id)
    )
    AND (
      o.organization_type IN ('government', 'service_provider', 'branch')
      OR EXISTS (
        SELECT 1 FROM public.service_agreements sa
        WHERE sa.provider_organization_id = o.id
          AND (sa.ends_on IS NULL OR sa.ends_on >= current_date)
      )
      OR EXISTS (
        SELECT 1 FROM public.organizations child
        WHERE child.parent_organization_id = o.id
      )
      OR EXISTS (
        SELECT 1 FROM public.org_engagements e2
        WHERE e2.to_org_id = o.id
          AND e2.status = 'active'
      )
    )
  ORDER BY st_area(o.jurisdiction_geom) ASC
  LIMIT 1;

  -- -- Layer 3: site geofence + zone --
  -- 0347: added z.location_id to the SELECT (into v_zone) so the
  -- ownership hop can prefer the house. Zone MATCHING itself is
  -- byte-unchanged from 0290.
  SELECT z.id, z.site_id, z.location_id, z.module_key, z.onsite_profile, z.boundary,
         z.jurisdiction_rule_set_id, z.rule_overrides,
         z.repeat_stay_radius_m, z.repeat_stay_window_nights,
         z.nightly_limit_consecutive, z.nightly_limit_monthly, z.scv_required
    INTO v_zone
  FROM public.location_zones z
  WHERE z.organization_id = p_org_id
    AND z.boundary IS NOT NULL
    AND z.boundary_verification = 'verified'
    AND ST_IsValid(z.boundary)
    AND NOT ST_IsEmpty(z.boundary)
    AND st_contains(z.boundary, v_point)
    AND (p_module_key IS NULL OR z.module_key = p_module_key)
    AND public._geofence_active_at(z.active_schedule, p_at)
  ORDER BY (z.parent_zone_id IS NOT NULL) DESC
  LIMIT 1;

  IF v_zone.id IS NOT NULL THEN
    v_site_id := v_zone.site_id;
    v_resolution := 'resolved';

    -- 0347 OWNERSHIP: the answer is ALWAYS THE HOUSE
    -- (locations.organization_id). site_id is a transitional
    -- COMPATIBILITY LINK (v2 ruling !1304) -- never a co-equal owner.
    -- So it is used only as a ROUTE to the house, not as an owner in
    -- its own right. Resolution tiers, all landing on the house:
    --   1. zone.location_id -> locations.organization_id       (direct house link)
    --   2. zone.site_id -> client_sites.location_id -> locations (site as ROUTE to house)
    --   3. zone.site_id -> client_sites.client_organization_id (transitional last-resort,
    --      only while a site has no house link yet during migration)
    -- On current data every zone.location_id is NULL and sites may not
    -- yet carry location_id, so resolution reaches tier 3 = the exact
    -- 0290 answer (client_sites.client_organization_id). Output is
    -- therefore IDENTICAL today; it becomes house-authoritative as
    -- step 2 populates location_id upward. Per the §5 ruling the three
    -- tiers return the SAME org by construction (same PLACE axis).

    -- Tier 1: zone carries a direct house link.
    IF v_zone.location_id IS NOT NULL THEN
      SELECT loc.organization_id
        INTO v_client_org
      FROM public.locations loc
      WHERE loc.id = v_zone.location_id;
    END IF;

    -- ON-SITE test stays on client_sites (the house has NO geometry).
    -- UNCHANGED from 0290. This block ALSO captures the site's own
    -- links so we can route to the house (tiers 2/3) when the zone
    -- had no direct location_id.
    IF v_site_id IS NOT NULL THEN
      DECLARE
        v_site_location_id uuid := null;
        v_site_client_org  uuid := null;
      BEGIN
        SELECT cs.location_id,
               cs.client_organization_id,
               CASE
                 WHEN v_zone.onsite_profile = 'approach_10m'
                   THEN st_dwithin(COALESCE(cs.center_point, cs.boundary)::geography, v_point::geography, 10)
                 ELSE
                   (cs.boundary IS NOT NULL AND st_contains(cs.boundary, v_point))
                   OR st_dwithin(COALESCE(cs.center_point, cs.boundary)::geography,
                                 v_point::geography,
                                 COALESCE(cs.onsite_radius_meters, 10))
               END
          INTO v_site_location_id, v_site_client_org, v_on_site
        FROM public.client_sites cs
        WHERE cs.id = v_site_id;
        v_on_site := COALESCE(v_on_site, false);

        -- Owner not yet resolved via the zone's direct house link:
        -- route THROUGH the site to its house (tier 2), and only if
        -- the site has no house yet, use the site's own owner column
        -- as the transitional last-resort (tier 3).
        IF v_client_org IS NULL THEN
          IF v_site_location_id IS NOT NULL THEN
            SELECT loc.organization_id
              INTO v_client_org
            FROM public.locations loc
            WHERE loc.id = v_site_location_id;
          END IF;
          -- Tier 3 transitional fallback.
          v_client_org := COALESCE(v_client_org, v_site_client_org);
        END IF;
      END;
    END IF;

    SELECT COALESCE(jrs.rules, '{}'::jsonb)
      INTO v_rules
    FROM public.jurisdiction_rule_sets jrs
    WHERE jrs.id = v_zone.jurisdiction_rule_set_id;

    v_rules := COALESCE(v_rules, '{}'::jsonb)
      || jsonb_strip_nulls(jsonb_build_object(
           'repeat_stay_radius_m',      v_zone.repeat_stay_radius_m,
           'repeat_stay_window_nights', v_zone.repeat_stay_window_nights,
           'nightly_limit_consecutive', v_zone.nightly_limit_consecutive,
           'nightly_limit_monthly',     v_zone.nightly_limit_monthly,
           'scv_required',              v_zone.scv_required
         ))
      || COALESCE(v_zone.rule_overrides, '{}'::jsonb);
  ELSE
    -- No verified zone matched. Determine WHY for the resolution_status.
    -- (UNCHANGED from 0290.)
    IF v_resolution NOT IN ('unresolved_no_geofence', 'unresolved_invalid', 'unresolved_unverified') THEN
      IF EXISTS (
        SELECT 1 FROM public.location_zones z
        WHERE z.organization_id = p_org_id
          AND z.boundary IS NOT NULL
          AND z.boundary_verification = 'unverified'
          AND ST_IsValid(z.boundary)
          AND NOT ST_IsEmpty(z.boundary)
          AND st_contains(z.boundary, v_point)
          AND (p_module_key IS NULL OR z.module_key = p_module_key)
          AND public._geofence_active_at(z.active_schedule, p_at)
      ) THEN
        v_resolution := 'unresolved_unverified';
      ELSIF EXISTS (
        SELECT 1 FROM public.location_zones z
        WHERE z.organization_id = p_org_id
          AND z.boundary IS NOT NULL
          AND (NOT ST_IsValid(z.boundary) OR ST_IsEmpty(z.boundary))
          AND st_contains(z.boundary, v_point)
          AND (p_module_key IS NULL OR z.module_key = p_module_key)
          AND public._geofence_active_at(z.active_schedule, p_at)
      ) THEN
        v_resolution := 'unresolved_invalid';
      ELSE
        IF NOT EXISTS (
          SELECT 1 FROM public.location_zones z
          WHERE z.organization_id = p_org_id
            AND z.boundary IS NOT NULL
            AND (p_module_key IS NULL OR z.module_key = p_module_key)
        ) THEN
          v_resolution := 'unresolved_no_geofence';
        END IF;
      END IF;
    END IF;
  END IF;

  RETURN QUERY SELECT
    v_in_bounds, v_oob_district, v_jur_id, v_jur_name,
    v_on_site, v_site_id, v_client_org,
    v_zone.id, v_zone.module_key, v_rules,
    v_resolution,
    v_gov_overlap;
END;
$$;


ALTER FUNCTION "public"."resolve_context"("p_lat" double precision, "p_lng" double precision, "p_org_id" "uuid", "p_module_key" "text", "p_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_context"("p_lat" double precision, "p_lng" double precision, "p_org_id" "uuid", "p_module_key" "text", "p_at" timestamp with time zone) IS 'Three-layer geofence resolution with verification gate (P1/P2) and role-aware governing jurisdiction. 0347 convergence step 1: the OWNERSHIP answer (client_org_id) ALWAYS resolves TO THE HOUSE (locations.organization_id) where a house is reachable. site_id is a transitional COMPATIBILITY LINK (v2 ruling !1304), used only as a ROUTE to the house, never as a co-equal owner. Resolution tiers: (1) zone.location_id -> locations; (2) zone.site_id -> client_sites.location_id -> locations (site as route); (3) zone.site_id -> client_sites.client_organization_id (transitional last-resort only while a site has no house link during migration). Per the owner ruling (2026-08-05) all three tiers return the SAME org by construction (same PLACE axis), so this changes the SOURCE of the answer, not the answer. ON-SITE geometry, zone matching, Layer 1/2, resolution_status, all 12 columns and governor_overlap_flag are byte-unchanged from 0290. Safe day-one: live zones have location_id NULL and their sites may not yet carry location_id, so resolution reaches tier 3 = the exact 0290 answer -> IDENTICAL output on current data; becomes house-authoritative as step 2 populates location_id upward.';



CREATE OR REPLACE FUNCTION "public"."resolve_enforcement_mode"("p_zone_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  select coalesce(
    lz.enforcement_workflow_override,
    o.enforcement_workflow_mode,
    'officer_direct'
  )
  from location_zones lz
  join organizations o on o.id = lz.organization_id
  where lz.id = p_zone_id;
$$;


ALTER FUNCTION "public"."resolve_enforcement_mode"("p_zone_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_enforcement_mode"("p_zone_id" "uuid") IS 'Effective enforcement workflow mode for a zone: zone override else org default (else officer_direct). Used by the field notice flow to gate direct issuance.';



CREATE OR REPLACE FUNCTION "public"."resolve_location_visibility"("p_sal_id" "uuid", "p_viewing_org_id" "uuid") RETURNS TABLE("share_contract_price" boolean, "share_actual_cost" boolean, "is_provider" boolean, "is_client" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    -- Effective share_contract_price: location override if set, else agreement default.
    coalesce(sal.share_contract_price, sa.default_share_contract_price) as share_contract_price,
    coalesce(sal.share_actual_cost,    sa.default_share_actual_cost)    as share_actual_cost,
    -- Which side of the agreement is the viewing org?
    public.org_access_allowed(sa.provider_organization_id) as is_provider,
    public.org_access_allowed(sa.client_organization_id)   as is_client
  from public.service_agreement_locations sal
  join public.service_agreements sa on sa.id = sal.service_agreement_id
  where sal.id = p_sal_id;
$$;


ALTER FUNCTION "public"."resolve_location_visibility"("p_sal_id" "uuid", "p_viewing_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_location_visibility"("p_sal_id" "uuid", "p_viewing_org_id" "uuid") IS 'Returns effective visibility settings for a location contract: share_contract_price and share_actual_cost (location override coalesced with agreement default), plus which side of the agreement the viewing org is on. Used by the UI finance tab and conductor egress gate (epic #179).';



CREATE OR REPLACE FUNCTION "public"."resolve_manager_for_user"("p_user_id" "uuid", "p_context_org_id" "uuid") RETURNS TABLE("manager_user_id" "uuid", "resolution_source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_manager_id     uuid;
  v_source         text;
  v_home_org_id    uuid;
  v_walk_org_id    uuid;
  v_parent_org_id  uuid;
BEGIN
  -- ── Step 1: Branch-specific line_manager at context org ──
  SELECT sr.reports_to_user_id INTO v_manager_id
  FROM public.staff_reporting sr
  WHERE sr.user_id = p_user_id
    AND sr.scope_org_id = p_context_org_id
    AND sr.relationship_type = 'line_manager'
    AND sr.effective_to IS NULL
  LIMIT 1;

  IF v_manager_id IS NOT NULL THEN
    manager_user_id := v_manager_id;
    resolution_source := 'branch_line_manager';
    RETURN NEXT;
    RETURN;
  END IF;

  -- ── Step 2: Org-wide line_manager (at user's home org) ──
  SELECT up.organization_id INTO v_home_org_id
  FROM public.user_profiles up
  WHERE up.id = p_user_id;

  IF v_home_org_id IS NOT NULL AND v_home_org_id <> p_context_org_id THEN
    SELECT sr.reports_to_user_id INTO v_manager_id
    FROM public.staff_reporting sr
    WHERE sr.user_id = p_user_id
      AND sr.scope_org_id = v_home_org_id
      AND sr.relationship_type = 'line_manager'
      AND sr.effective_to IS NULL
    LIMIT 1;

    IF v_manager_id IS NOT NULL THEN
      manager_user_id := v_manager_id;
      resolution_source := 'org_wide_line_manager';
      RETURN NEXT;
      RETURN;
    END IF;
  END IF;

  -- ── Step 3: Team lead fallback ──
  SELECT t.team_lead_user_id INTO v_manager_id
  FROM public.team_members tm
  JOIN public.teams t ON tm.team_id = t.id
  WHERE tm.user_id = p_user_id
    AND tm.left_at IS NULL
    AND t.status = 'active'
    AND (t.scope_org_id = p_context_org_id OR t.scope_org_id IS NULL)
    AND t.team_lead_user_id IS NOT NULL
    AND t.team_lead_user_id <> p_user_id  -- prevent self-reference
  LIMIT 1;

  IF v_manager_id IS NOT NULL THEN
    manager_user_id := v_manager_id;
    resolution_source := 'team_lead';
    RETURN NEXT;
    RETURN;
  END IF;

  -- ── Step 4: Branch manager by role_at_branch + org tree walk (Q2) ──
  -- Start at the context org, then walk up parent_organization_id
  v_walk_org_id := p_context_org_id;

  LOOP
    SELECT sba.user_id INTO v_manager_id
    FROM public.staff_branch_authorisations sba
    WHERE sba.branch_org_id = v_walk_org_id
      AND sba.role_at_branch = 'branch_manager'
      AND sba.status = 'active'
      AND sba.user_id <> p_user_id  -- prevent self-reference
    LIMIT 1;

    IF v_manager_id IS NOT NULL THEN
      manager_user_id := v_manager_id;
      resolution_source := CASE
        WHEN v_walk_org_id = p_context_org_id THEN 'branch_manager'
        ELSE 'tree_walk_branch_manager'
      END;
      RETURN NEXT;
      RETURN;
    END IF;

    -- Walk up the org tree
    SELECT o.parent_organization_id INTO v_parent_org_id
    FROM public.organizations o
    WHERE o.id = v_walk_org_id;

    -- No parent or reached the root -- stop walking
    IF v_parent_org_id IS NULL THEN
      EXIT;
    END IF;

    v_walk_org_id := v_parent_org_id;
  END LOOP;

  -- ── Step 5: No manager found ──
  RETURN;
END;
$$;


ALTER FUNCTION "public"."resolve_manager_for_user"("p_user_id" "uuid", "p_context_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_manager_for_user"("p_user_id" "uuid", "p_context_org_id" "uuid") IS '4-step manager resolver with org-tree walk fallback. Returns (manager_user_id, resolution_source). Steps: (1) branch-specific line_manager, (2) org-wide line_manager, (3) team lead, (4) branch_manager by role + tree walk. Returns zero rows if none found. SECURITY DEFINER for system-level consumers (speak-up, welfare). #224.';



CREATE OR REPLACE FUNCTION "public"."resolve_retention_days"("p_org_id" "uuid", "p_module_key" "text", "p_category" "text") RETURNS integer
    LANGUAGE "sql" STABLE
    AS $$
  select retention_days
  from public.retention_policies
  where category = p_category
    and is_active
    and (
      (organization_id = p_org_id and module_key = p_module_key)
      or (organization_id = p_org_id and module_key is null)
      or (organization_id is null and module_key is null)
    )
  order by
    -- most specific wins: org+module, then org, then platform
    (organization_id is not null and module_key is not null) desc,
    (organization_id is not null) desc
  limit 1;
$$;


ALTER FUNCTION "public"."resolve_retention_days"("p_org_id" "uuid", "p_module_key" "text", "p_category" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_retention_days"("p_org_id" "uuid", "p_module_key" "text", "p_category" "text") IS 'Effective retention days for (org, module, category): module policy -> org default -> platform default. Drives observations.retention_until; periods are per-council, not hardcoded.';



CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


