CREATE OR REPLACE FUNCTION "public"."tg_align_module_subscription"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_org_type text;
begin
  -- Only act when the enabled flag is set (INSERT) or actually changed (UPDATE).
  if tg_op = 'UPDATE' and (new.enabled is not distinct from old.enabled) then
    return new;
  end if;

  select organization_type into v_org_type
  from public.organizations
  where id = new.organization_id;

  -- Layer 1 bills providers only. Non-provider orgs no-op.
  if v_org_type is null or v_org_type not in ('service_provider', 'branch') then
    return new;
  end if;

  if new.enabled then
    -- Create or reactivate the line. Preserve any existing per-provider overrides
    -- (only status/updated_at are forced; price columns are left untouched).
    insert into public.org_module_subscriptions (organization_id, module_key, status)
    values (new.organization_id, new.module_key, 'active')
    on conflict (organization_id, module_key) do update
      set status = case
                     when public.org_module_subscriptions.status = 'cancelled'
                       then public.org_module_subscriptions.status  -- do not silently revive a cancelled contract
                     else 'active'
                   end,
          updated_at = now();
  else
    -- Disable => suspend the line (never delete; keeps overrides + history).
    update public.org_module_subscriptions
       set status = 'suspended', updated_at = now()
     where organization_id = new.organization_id
       and module_key = new.module_key
       and status <> 'cancelled';
  end if;

  return new;
end $$;


ALTER FUNCTION "public"."tg_align_module_subscription"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."tg_align_module_subscription"() IS 'B2 (#2): aligns org_module_subscriptions with organization_modules enablement for billable provider tiers (service_provider|branch). Preserves overrides; suspends (never deletes) on disable; does not revive cancelled contracts.';



CREATE OR REPLACE FUNCTION "public"."tg_observations_enforce_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  -- CONDITION A: post-lock edit (row was already locked before this UPDATE).
  if old.locked_at is not null then
    -- Block clearing or rewriting locked_at.
    if new.locked_at is distinct from old.locked_at then
      raise exception
        'observation % is locked. locked_at may not be cleared or rewritten. Use the authorised correction path.',
        old.id
        using errcode = 'P0001';
    end if;
    -- Block changes to frozen fact fields.
    if (
      new.observed_at       is distinct from old.observed_at       or
      new.gps_lat           is distinct from old.gps_lat           or
      new.gps_lng           is distinct from old.gps_lng           or
      new.plate_number      is distinct from old.plate_number      or
      new.is_compliant      is distinct from old.is_compliant      or
      new.compliance_reason is distinct from old.compliance_reason or
      new.officer_id        is distinct from old.officer_id        or
      new.zone_id           is distinct from old.zone_id
    ) then
      raise exception
        'observation % is locked (locked_at = %). Frozen fact fields may not be edited after lock. Authorised corrections require the correction workflow (Part 2, not yet built).',
        old.id, old.locked_at
        using errcode = 'P0001';
    end if;
  end if;

  -- CONDITION B: lock-transition tamper (this UPDATE causes the row to become locked).
  -- The normal completion write sets photo fields only and must pass through.
  -- A tampered write that also changes frozen fields must be blocked.
  if old.locked_at is null and new.locked_at is not null then
    if (
      new.observed_at       is distinct from old.observed_at       or
      new.gps_lat           is distinct from old.gps_lat           or
      new.gps_lng           is distinct from old.gps_lng           or
      new.plate_number      is distinct from old.plate_number      or
      new.is_compliant      is distinct from old.is_compliant      or
      new.compliance_reason is distinct from old.compliance_reason or
      new.officer_id        is distinct from old.officer_id        or
      new.zone_id           is distinct from old.zone_id
    ) then
      raise exception
        'observation % cannot be locked with mutated frozen fields. Frozen fact fields must be unchanged at the moment of lock.',
        old.id
        using errcode = 'P0001';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."tg_observations_enforce_lock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_observations_lock_on_completion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  -- Transition-based: only fire when photo_captured_at goes NULL -> NOT NULL.
  -- Never fires if photo_captured_at was already set, or if it stays null.
  if (old.photo_captured_at is null and new.photo_captured_at is not null) then
    -- Write-once: only set locked_at if not already set (idempotent).
    if new.locked_at is null then
      new.locked_at := now();
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."tg_observations_lock_on_completion"() OWNER TO "postgres";


