CREATE OR REPLACE FUNCTION "public"."validate_assignment_location_access"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_assignment_org_id uuid;
  v_site_id           uuid := null;
  v_zone_id           uuid := null;
  v_has_access        boolean;
begin
  -- Resolve the assignment org from patrol_routes.
  select organization_id into v_assignment_org_id
    from public.patrol_routes
   where id = new.patrol_route_id;

  if v_assignment_org_id is null then
    raise exception 'Assignment (patrol_route_id=%) not found or has no organization_id.', new.patrol_route_id;
  end if;

  -- Determine which location is being added.
  if tg_table_name = 'patrol_route_sites' then
    v_site_id := new.site_id;
  else
    v_zone_id := new.zone_id;
  end if;

  -- Check ownership: does the assignment org own the location?
  if v_site_id is not null then
    select exists (
      select 1 from public.client_sites
      where id = v_site_id
        and client_organization_id = v_assignment_org_id
    ) into v_has_access;
  else
    select exists (
      select 1 from public.location_zones
      where id = v_zone_id
        and organization_id = v_assignment_org_id
    ) into v_has_access;
  end if;

  -- If not owner, check for an active service_agreement_locations row
  -- where the assignment org is the provider.
  if not v_has_access then
    select exists (
      select 1
      from public.service_agreement_locations sal
      join public.service_agreements sa on sa.id = sal.service_agreement_id
      where sal.status = 'active'
        and (sal.site_id = v_site_id or sal.zone_id = v_zone_id)
        and sa.provider_organization_id = v_assignment_org_id
    ) into v_has_access;
  end if;

  if not v_has_access then
    raise exception
      'Cannot add location to assignment: org % does not own this location and has no active service agreement for it. Create a service_agreement_locations row first.',
      v_assignment_org_id
      using errcode = 'P0001';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_assignment_location_access"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_assignment_location_access"() IS 'Trigger: validates that the assignment org owns the location OR has an active service_agreement_locations row before allowing a location to be added to an assignment (patrol_route_sites / patrol_route_zones). QA gap G4, epic #179.';



CREATE OR REPLACE FUNCTION "public"."validate_dispatch_job_service_agreement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_site_agreement_id uuid;
begin
  if new.client_site_id is null then
    return new;
  end if;

  select cs.service_agreement_id
    into v_site_agreement_id
  from public.client_sites cs
  where cs.id = new.client_site_id;

  if v_site_agreement_id is not null then
    if new.service_agreement_id is null then
      new.service_agreement_id := v_site_agreement_id;
    elsif new.service_agreement_id <> v_site_agreement_id then
      raise exception
        'dispatch_jobs.service_agreement_id (%) must match client_sites.service_agreement_id (%) for client_site_id (%)',
        new.service_agreement_id, v_site_agreement_id, new.client_site_id;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_dispatch_job_service_agreement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_ta_names"("p_names" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_result jsonb := '[]'::jsonb;
  v_name text;
  v_match text;
  v_suggestions jsonb;
  v_entry jsonb;
BEGIN
  -- If the canonical_ta_names table is empty, return all as valid
  -- (defence in depth: do not block proposals when the table has not
  -- been populated yet; the executor still validates against the live
  -- NZTA source).
  IF NOT EXISTS (SELECT 1 FROM public.canonical_ta_names LIMIT 1) THEN
    FOR i IN 1..array_length(p_names, 1) LOOP
      v_result := v_result || jsonb_build_object(
        'name', p_names[i],
        'valid', true,
        'suggestions', '[]'::jsonb,
        'note', 'canonical_ta_names table is empty; validation deferred to executor'
      );
    END LOOP;
    RETURN v_result;
  END IF;

  FOREACH v_name IN ARRAY p_names LOOP
    -- Exact match (case-insensitive)
    SELECT ta_name INTO v_match
    FROM public.canonical_ta_names
    WHERE upper(ta_name) = upper(trim(v_name))
    LIMIT 1;

    IF v_match IS NOT NULL THEN
      v_result := v_result || jsonb_build_object(
        'name', v_name,
        'valid', true,
        'canonical_name', v_match,
        'suggestions', '[]'::jsonb
      );
    ELSE
      -- No exact match: compute top 3 fuzzy suggestions by Levenshtein distance
      SELECT jsonb_agg(sub.ta_name ORDER BY sub.dist, sub.ta_name)
      INTO v_suggestions
      FROM (
        SELECT c.ta_name,
               levenshtein(upper(trim(v_name)), upper(c.ta_name)) AS dist
        FROM public.canonical_ta_names c
        ORDER BY dist ASC
        LIMIT 3
      ) sub;

      v_result := v_result || jsonb_build_object(
        'name', v_name,
        'valid', false,
        'suggestions', COALESCE(v_suggestions, '[]'::jsonb)
      );
    END IF;
  END LOOP;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."validate_ta_names"("p_names" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_ta_names"("p_names" "text"[]) IS 'Validate TA names against canonical_ta_names. Returns JSON array with valid/invalid status and Levenshtein-based fuzzy suggestions for invalid names. Phase 2 geofence redesign (epic #226).';



CREATE OR REPLACE FUNCTION "public"."verify_boundary"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_org_id   uuid;
  v_uid      uuid := auth.uid();
  v_boundary geometry;
  v_et       text;  -- normalised entity_type for history table
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'verify_boundary: not authenticated';
  END IF;

  IF p_entity_type = 'organization' THEN
    SELECT id, jurisdiction_geom INTO v_org_id, v_boundary
      FROM public.organizations WHERE id = p_entity_id;
    IF NOT FOUND THEN RETURN false; END IF;
    IF NOT is_admin_for_org(v_org_id) THEN
      RAISE EXCEPTION 'verify_boundary: access denied for organization %', p_entity_id;
    END IF;
    UPDATE public.organizations
       SET jurisdiction_verification = 'verified',
           jurisdiction_verified_by  = v_uid,
           jurisdiction_verified_at  = now()
     WHERE id = p_entity_id;
    v_et := 'organization';

  ELSIF p_entity_type = 'location_zone' THEN
    SELECT organization_id, boundary INTO v_org_id, v_boundary
      FROM public.location_zones WHERE id = p_entity_id;
    IF NOT FOUND THEN RETURN false; END IF;
    IF NOT is_admin_for_org(v_org_id) THEN
      RAISE EXCEPTION 'verify_boundary: access denied for location_zone %', p_entity_id;
    END IF;
    UPDATE public.location_zones
       SET boundary_verification = 'verified',
           boundary_verified_by  = v_uid,
           boundary_verified_at  = now()
     WHERE id = p_entity_id;
    v_et := 'location_zone';

  ELSIF p_entity_type = 'client_site' THEN
    SELECT client_organization_id, boundary INTO v_org_id, v_boundary
      FROM public.client_sites WHERE id = p_entity_id;
    IF NOT FOUND THEN RETURN false; END IF;
    IF NOT org_access_allowed(v_org_id) THEN
      RAISE EXCEPTION 'verify_boundary: access denied for client_site %', p_entity_id;
    END IF;
    UPDATE public.client_sites
       SET boundary_verification = 'verified',
           boundary_verified_by  = v_uid,
           boundary_verified_at  = now()
     WHERE id = p_entity_id;
    v_et := 'client_site';

  ELSIF p_entity_type = 'patrol_checkpoint' THEN
    -- Checkpoints are NOT in the boundary history table (point geometry,
    -- not polygon boundary). Still update verification state but skip history.
    SELECT organization_id INTO v_org_id
      FROM public.patrol_checkpoints WHERE id = p_entity_id;
    IF NOT FOUND THEN RETURN false; END IF;
    IF NOT is_admin_for_org(v_org_id) THEN
      RAISE EXCEPTION 'verify_boundary: access denied for patrol_checkpoint %', p_entity_id;
    END IF;
    UPDATE public.patrol_checkpoints
       SET checkpoint_verification = 'verified',
           checkpoint_verified_by  = v_uid,
           checkpoint_verified_at  = now()
     WHERE id = p_entity_id;
    RETURN true;  -- early return, no history row for checkpoints

  ELSE
    RAISE EXCEPTION 'verify_boundary: unknown entity_type "%"', p_entity_type;
  END IF;

  -- Record the verification event in history
  INSERT INTO public.geofence_boundary_history (
    entity_type, entity_id, boundary, boundary_source,
    verification_state, verified_by, verified_at,
    changed_by, changed_via, change_reason, version
  ) VALUES (
    v_et, p_entity_id, v_boundary, NULL,
    'verified', v_uid, now(),
    v_uid, 'verification', 'Boundary verified via visual map confirmation',
    public._gbh_next_version(v_et, p_entity_id)
  );

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."verify_boundary"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."verify_boundary"("p_entity_type" "text", "p_entity_id" "uuid") IS 'Sets the verification state of a geofence-bearing entity to verified. Records a history row for the unverified->verified transition. Gated by org_access_allowed / is_admin_for_org. Phase 1A+4 (#226).';


