    CONSTRAINT "client_site_patrol_config_module_key_check" CHECK (("module_key" = ANY (ARRAY['freedom_camping'::"text", 'parking_enforcement'::"text", 'noise_control'::"text", 'biosecurity'::"text", 'smoke_complaints'::"text", 'static_guarding'::"text", 'access_control'::"text", 'ems'::"text", 'alarm_response'::"text", 'welfare_check'::"text", 'general_patrol'::"text"]))),
