    "prompt_radius_meters" integer DEFAULT 30 NOT NULL,
    "onsite_radius_meters" integer DEFAULT 10 NOT NULL,
    "site_origin" "text" DEFAULT 'contracted'::"text" NOT NULL,
    "module_title" "text",
    "ownership_status" "text" DEFAULT 'resolved'::"text" NOT NULL,
    "ownership_signals" "jsonb",
    "address_match_key" "text",
    "external_ref" "text",
    "internal_client_ref" "text",
    "boundary_status" "text" DEFAULT 'authoritative'::"text" NOT NULL,
    "location_id" "uuid",
    "external_refs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "boundary_verification" "text" DEFAULT 'unverified'::"text" NOT NULL,
    "boundary_verified_by" "uuid",
