);


ALTER TABLE "public"."monthly_report_packs" OWNER TO "postgres";


COMMENT ON TABLE "public"."monthly_report_packs" IS 'Generated monthly report packs per service agreement. One row per period+template, with a JSONB data snapshot, PDF path, and delivery log. Feeds the client portal (3.3).';



CREATE TABLE IF NOT EXISTS "public"."noise_assessments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "dispatch_job_id" "uuid",
    "officer_user_id" "uuid",
    "location_id" "uuid",
    "decibel_reading" real,
    "noise_source" "text",
    "prior_notice_count" integer DEFAULT 0 NOT NULL,
    "prior_notice_types" "text"[],
    "permanent_end_active" boolean DEFAULT false NOT NULL,
    "hs_flag_active" boolean DEFAULT false NOT NULL,
    "hs_notes" "text",
    "bob_recommendation" "text",
    "action_taken" "text",
    "scene_description" "text",
    "assessed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "officer_id" "uuid",
    "officer_name" "text",
    "site_id" "uuid",
    "source" "text",
    "time_of_day" time without time zone,
    "prior_notices" integer DEFAULT 0 NOT NULL,
    "action" "text",
    "notice_number" "text",
    "follow_up_required" boolean DEFAULT false NOT NULL,
    "follow_up_at" timestamp with time zone,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "notes" "text",
    "bob_classification" "text",
    "bob_confidence" real,
    "volume_score" smallint,
    "time_score" smallint,
    "tone_score" smallint,
    "matrix_total" smallint,
    "visit_number_tonight" integer DEFAULT 1 NOT NULL,
    "is_problem_address" boolean DEFAULT false NOT NULL,
    "end_number" "text",
    "occupant_name" "text",
    "prior_end_within_72hrs" boolean DEFAULT false NOT NULL,
    "permanent_abatement_active" boolean DEFAULT false NOT NULL,
    "occupant_cooperative" boolean,
    "police_requested" boolean DEFAULT false NOT NULL,
    "police_present" boolean DEFAULT false NOT NULL,
    "received_at" timestamp with time zone,
    "arrived_at" timestamp with time zone,
    "departed_at" timestamp with time zone,
    "hs_checklist_completed" boolean DEFAULT false NOT NULL,
    "hs_checklist_items" "jsonb" DEFAULT '[]'::"jsonb",
    "hs_abort_reason" "text",
    "referred_animal_control" boolean DEFAULT false NOT NULL,
    "incident_report_text" "text",
    "complainant_protected" boolean DEFAULT true NOT NULL,
    "assessment_location" "text",
    "assessment_gps_lat" double precision,
    "assessment_gps_lng" double precision,
    "assessment_gps_accuracy" real,
    "noise_source_address" "text",
    "noise_source_gps_lat" double precision,
    "noise_source_gps_lng" double precision,
    "arrival_gps_lat" double precision,
    "arrival_gps_lng" double precision,
    "arrival_gps_accuracy" real,
    "address_discrepancy_noted" boolean DEFAULT false NOT NULL,
    "address_discrepancy_reason" "text",
    "photo_assessment_point" "jsonb" DEFAULT '[]'::"jsonb",
    "photo_source_address" "jsonb" DEFAULT '[]'::"jsonb",
    "photo_service_evidence" "jsonb" DEFAULT '[]'::"jsonb",
    "evidence_package_url" "text",
    "job_number" "text",
    "occupant_dob" "date",
    "is_large_event_or_commercial" boolean,
    "supplementary_scores" "jsonb",
    "photo_urls" "jsonb" DEFAULT '[]'::"jsonb",
    "complaint_address" "text",
    "complainant_site_id" "uuid",
