    "permit_reference" "text",
    "compliance_status" "text",
    "evidence_id" "uuid",
    "notes" "text",
    "observed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "parking_sessions_compliance_status_check" CHECK (("compliance_status" = ANY (ARRAY['compliant'::"text", 'timed_out'::"text", 'no_permit'::"text", 'breach'::"text"])))
);


ALTER TABLE "public"."parking_sessions" OWNER TO "postgres";


COMMENT ON TABLE "public"."parking_sessions" IS 'Parking enforcement chalk pass and permit check records. Links vehicle, zone, officer, and compliance verdict.';



CREATE TABLE IF NOT EXISTS "public"."patrol_checkpoint_visits" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "patrol_id" "uuid" NOT NULL,
    "checkpoint_id" "uuid" NOT NULL,
    "officer_user_id" "uuid",
    "gps_lat" double precision,
    "gps_lng" double precision,
    "visited_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "scan_method" "text" DEFAULT 'url_deep_link'::"text" NOT NULL,
    "gps_accuracy" double precision,
    "gps_distance_from_checkpoint" double precision,
    "within_radius" boolean,
    "notes" "text",
    "shift_stop_id" "uuid",
    CONSTRAINT "patrol_checkpoint_visits_scan_method_check" CHECK (("scan_method" = ANY (ARRAY['qr_camera'::"text", 'nfc'::"text", 'manual_code'::"text", 'url_deep_link'::"text"])))
);


ALTER TABLE "public"."patrol_checkpoint_visits" OWNER TO "postgres";


COMMENT ON TABLE "public"."patrol_checkpoint_visits" IS 'Officer QR scan events at patrol checkpoints. Proves attendance and timing.';



COMMENT ON COLUMN "public"."patrol_checkpoint_visits"."scan_method" IS 'How the visit was captured: qr_camera | nfc | manual_code | url_deep_link.';



COMMENT ON COLUMN "public"."patrol_checkpoint_visits"."gps_distance_from_checkpoint" IS 'Haversine metres between the officer GPS fix and the checkpoint at scan time.';



COMMENT ON COLUMN "public"."patrol_checkpoint_visits"."within_radius" IS 'Whether the officer was within the expected check-in radius at scan time.';



COMMENT ON COLUMN "public"."patrol_checkpoint_visits"."shift_stop_id" IS 'The engine shift_stop this checkpoint visit fulfils, when resolvable. Null when no unambiguous stop matches (the checkpoint->site mapping is resolved by P5). Enables per-stop completion + missed-checkpoint detection.';



CREATE TABLE IF NOT EXISTS "public"."patrol_checkpoints" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "location_id" "uuid",
    "name" "text" NOT NULL,
    "description" "text",
    "gps_lat" double precision,
    "gps_lng" double precision,
    "qr_code" "text",
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_site_id" "uuid",
    "radius_meters" integer DEFAULT 5 NOT NULL,
    "checkpoint_verification" "text" DEFAULT 'unverified'::"text" NOT NULL,
    "checkpoint_verified_by" "uuid",
    "checkpoint_verified_at" timestamp with time zone,
    "zone_id" "uuid",
    CONSTRAINT "patrol_checkpoints_checkpoint_verification_check" CHECK (("checkpoint_verification" = ANY (ARRAY['unverified'::"text", 'verified'::"text"]))),
    CONSTRAINT "patrol_checkpoints_one_anchor_chk" CHECK (("num_nonnulls"("client_site_id", "zone_id") = 1))
);


ALTER TABLE "public"."patrol_checkpoints" OWNER TO "postgres";


COMMENT ON TABLE "public"."patrol_checkpoints" IS 'QR checkpoint definitions. Officers scan these to prove attendance at patrol route stops.';



COMMENT ON COLUMN "public"."patrol_checkpoints"."client_site_id" IS 'The site this checkpoint belongs to (Tier 3 of the geofence hierarchy). Anchor for geofence nesting AND per-site KPI/reporting rollups (checkpoint -> site -> client org -> provider branch). Nullable + ON DELETE SET NULL so deleting a site preserves checkpoint history.';



COMMENT ON COLUMN "public"."patrol_checkpoints"."radius_meters" IS 'Radius (metres) of the small on-checkpoint proximity zone (Tier 4). Owner default 5 m. An officer within this radius of the checkpoint point registers the checkpoint.';



